const JSONL_SCHEMA: &str = "kitsu.chat.v1";
static JSONL_SUMMARY_EMITTED: AtomicBool = AtomicBool::new(false);
/// `-o` is a host-owned sink, so a run with no fully committed assistant must
/// say that the destination was preserved instead of making automation infer
/// a no-op from the absence of an installation receipt.
static OUTPUT_LAST_MESSAGE_REQUESTED: AtomicBool = AtomicBool::new(false);
static FULLY_COMMITTED_ASSISTANT_SEEN: AtomicBool = AtomicBool::new(false);
/// Process-entry clock used by both human model-command receipts and JSONL's
/// terminal summary. `Instant` avoids wall-clock jumps; conversion saturates
/// for completeness even though a CLI process cannot realistically reach it.
static RUN_STARTED_AT: OnceLock<Instant> = OnceLock::new();
/// Set only by inference-capable commands, keeping management/help output free
/// of an unrelated timing footer.
static MODEL_COMMAND_ACTIVE: AtomicBool = AtomicBool::new(false);
/// Distinguishes structurally child-free inference preflight from a carrier
/// that has begun a provider turn. Only the former may use the top-level
/// fallback's `Joined` cleanup fact without guessing.
static MODEL_INFERENCE_STARTED: AtomicBool = AtomicBool::new(false);
/// One phase owner for the inference-capable process run. Carrier helpers must
/// advance this instance instead of constructing presentation-local owners.
static PROCESS_RUN_LIFECYCLE: OnceLock<Mutex<kitsu_core::RunLifecycle>> = OnceLock::new();
static PROCESS_TERMINAL_FACTS: OnceLock<ProcessTerminalFacts> = OnceLock::new();
static PROCESS_INTERACTIVE_TERMINAL_FACTS: OnceLock<InteractiveTerminalFacts> = OnceLock::new();
static PROCESS_INFERENCE_CARRIER: OnceLock<InferenceCarrier> = OnceLock::new();
static PROCESS_PUBLISHED_RUN: OnceLock<kitsu_core::PublishedRun> = OnceLock::new();
/// Set only when `--allow-turn-errors` converts a scripted run with both a
/// success and a failure into an accepted partial result. The process-level
/// timing footer otherwise sees only exit code 0 and would mislabel it `ok`.
static SCRIPT_ACCEPTED_PARTIAL: AtomicBool = AtomicBool::new(false);
/// Last terminal assistant disposition observed in this process-run. Zero is
/// the valid initial `Absent` state.
static RUN_ASSISTANT_DISPOSITION: AtomicU8 = AtomicU8::new(0);
/// Exact count of semantically successful requested operations mirrored into
/// JSONL's terminal summary. Scripted execution owns its authoritative local
/// count (notably, `/quit` is control flow rather than a successful operation)
/// and stores it at finalization. Single-operation commands record a success
/// only after accepting a catalog result or committing a model answer.
static SUCCESSFUL_OPERATIONS: AtomicUsize = AtomicUsize::new(0);
static OUTPUT_SCHEMA: OnceLock<structured_output::OutputSchema> = OnceLock::new();
/// Terminal durability state mirrored into `final_summary`. A fresh session has
/// a planned id before its first snapshot exists; exposing that id as resumable
/// sent automation toward a file that was never created. Keep the plan and its
/// materialization state together so the terminal id/state receipt cannot
/// disagree (cycle-18 automation audit).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SessionSnapshotState {
    Disabled,
    PendingUntilFirstSuccess,
    Resumable,
}

impl SessionSnapshotState {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Disabled => "disabled",
            Self::PendingUntilFirstSuccess => "pending_until_first_success",
            Self::Resumable => "resumable",
        }
    }
}

#[derive(Debug)]
struct JsonlSessionReceipt {
    planned_id: Option<String>,
    snapshot_state: SessionSnapshotState,
    persistence_state: kitsu_core::RunPersistenceState,
}

impl JsonlSessionReceipt {
    const fn new(planned_id: Option<String>, snapshot_state: SessionSnapshotState) -> Self {
        let persistence_state = match snapshot_state {
            SessionSnapshotState::Disabled => kitsu_core::RunPersistenceState::NotRequested,
            SessionSnapshotState::PendingUntilFirstSuccess | SessionSnapshotState::Resumable => {
                kitsu_core::RunPersistenceState::Preserved
            }
        };
        Self {
            planned_id,
            snapshot_state,
            persistence_state,
        }
    }

    const fn disabled() -> Self {
        Self::new(None, SessionSnapshotState::Disabled)
    }

    fn terminal_id(&self) -> Option<String> {
        (self.snapshot_state == SessionSnapshotState::Resumable)
            .then(|| self.planned_id.clone())
            .flatten()
    }

    const fn persistence_state(&self) -> kitsu_core::RunPersistenceState {
        self.persistence_state
    }

    fn mark_committed(&mut self, session_id: &str) {
        self.planned_id = Some(session_id.to_string());
        self.snapshot_state = SessionSnapshotState::Resumable;
        self.persistence_state = kitsu_core::RunPersistenceState::Committed;
    }

    fn mark_failed(&mut self) {
        if self.persistence_state != kitsu_core::RunPersistenceState::NotRequested {
            self.persistence_state = kitsu_core::RunPersistenceState::Failed;
        }
    }
}

static JSONL_SESSION_RECEIPT: Mutex<JsonlSessionReceipt> =
    Mutex::new(JsonlSessionReceipt::disabled());
// Count pending and active approval readers. A claimant increments before it
// waits for the stdin mutex so type-ahead cannot repeatedly reacquire the lock
// and starve the authority prompt. A count also avoids a false inactive window
// when more than one prompt is waiting.
static APPROVAL_INPUT_ACTIVE: AtomicUsize = AtomicUsize::new(0);
static APPROVAL_INPUT_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
/// Card **T3-S7b**: the in-loop approval read's hand-off.
///
/// When a pinned pane is published the prompter does **not** claim stdin
/// (`APPROVAL_INPUT_ACTIVE` stays at zero, so the collector never drops its
/// `RawStdinGuard` and the kernel never echoes a thing). It parks the sending
/// half of a one-shot channel here and blocks on the receiving half; the live
/// collector takes the sender on its next tick, reads one key with raw mode
/// still engaged, and sends it back. `None` is "the read was closed without a
/// decision" -- EOF, a dead reader, or a cancelled turn.
///
/// Process-global for `MODAL_PANE`'s reason: the prompter runs on the tool
/// executor and the reader is the type-ahead collector's thread.
static APPROVAL_KEY_REQUEST: std::sync::Mutex<Option<std::sync::mpsc::Sender<Option<char>>>> =
    std::sync::Mutex::new(None);
/// Whether a live raw-mode collector is running and able to serve
/// [`APPROVAL_KEY_REQUEST`]. Published by `run_live_typeahead` while it holds
/// its `RawStdinGuard`, and cleared when it lets the guard go for any reason
/// (an approval claim, a job-control signal, the end of the turn). A prompter
/// only bypasses the claim protocol while this is true, and a waiting
/// prompter gives up the moment it goes false -- which is what makes "the
/// collector is gone" an interrupt instead of a hang.
static APPROVAL_KEY_READER: AtomicBool = AtomicBool::new(false);
/// Serializes in-loop approval reads with each other.
///
/// Deliberately **not** `APPROVAL_INPUT_LOCK`: that mutex is `try_lock`ed by
/// the collector on every 50 ms tick, and `std::sync::Mutex` is not fair, so
/// a thread that blocks on it without first publishing a claim is starved
/// indefinitely -- the very failure `ApprovalInputGuard::enter`'s comment
/// describes, measured here as a 20 s approval that never painted. The in-loop
/// path publishes no claim (publishing one is what makes the collector hand
/// the terminal back, which is the echo this card removes), so it needs a
/// mutex the collector never touches.
static APPROVAL_PANE_READ_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
static FOREGROUND_CANCELLED: AtomicBool = AtomicBool::new(false);
static ACTIVE_QUIT_CANCEL: AtomicBool = AtomicBool::new(false);
static ASSISTIVE_INPUT_INTERRUPTED: AtomicBool = AtomicBool::new(false);
const PROMPT_QUEUE_CAPACITY: usize = 8;
const STEERING_CAPACITY: usize = 4;

/// Human diagnostics are silent in JSONL automation mode. Errors that can no
/// longer be framed because stdout itself failed use `std::eprintln!` directly.
macro_rules! eprintln {
    () => {
        if !jsonl_requested() {
            std::eprintln!();
        }
    };
    ($($arg:tt)*) => {
        if !jsonl_requested() {
            std::eprintln!($($arg)*);
        }
    };
}

fn jsonl_requested() -> bool {
    std::env::args_os()
        .skip(1)
        .take_while(|arg| arg != "--")
        .any(|arg| arg == "--jsonl" || arg.to_str().is_some_and(|arg| arg.starts_with("--jsonl=")))
}

fn run_spec() -> &'static kitsu_core::RunSpec {
    static RUN_SPEC: OnceLock<kitsu_core::RunSpec> = OnceLock::new();
    RUN_SPEC.get_or_init(|| {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let run_id = kitsu_core::RunId::new(format!("{}-{nanos}", std::process::id()))
            .expect("process-generated run identity is machine-safe and bounded");
        kitsu_core::RunSpec::new(run_id)
    })
}

fn run_id() -> &'static str {
    run_spec().run_id().as_str()
}

fn process_run_lifecycle() -> &'static Mutex<kitsu_core::RunLifecycle> {
    PROCESS_RUN_LIFECYCLE.get_or_init(|| Mutex::new(kitsu_core::RunLifecycle::accept(run_spec())))
}

fn activate_model_command(carrier: InferenceCarrier) -> Result<(), CliError> {
    PROCESS_INFERENCE_CARRIER.set(carrier).map_err(|_| {
        CliError::user("internal inference carrier was initialized more than once".to_string())
    })?;
    MODEL_COMMAND_ACTIVE.store(true, Ordering::Release);
    let _ = process_run_lifecycle();
    Ok(())
}

fn mark_model_inference_started() {
    MODEL_INFERENCE_STARTED.store(true, Ordering::Release);
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ProcessTerminalFacts {
    cleanup: kitsu_core::RunCleanupState,
    persistence: kitsu_core::RunPersistenceState,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct InteractiveTerminalFacts {
    outcome: kitsu_core::RunOutcomeClass,
    assistant: kitsu_core::RunAssistantDisposition,
    cleanup: kitsu_core::RunCleanupState,
    persistence: kitsu_core::RunPersistenceState,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct InteractiveRunAggregate {
    successful_operation: bool,
    primary_non_success: Option<kitsu_core::RunOutcomeClass>,
    assistant: kitsu_core::RunAssistantDisposition,
    cleanup: kitsu_core::RunCleanupState,
    replaced_turns: u32,
}

impl Default for InteractiveRunAggregate {
    fn default() -> Self {
        Self {
            successful_operation: false,
            primary_non_success: None,
            assistant: kitsu_core::RunAssistantDisposition::Absent,
            cleanup: kitsu_core::RunCleanupState::Joined,
            replaced_turns: 0,
        }
    }
}

impl InteractiveRunAggregate {
    fn record_non_success(&mut self, outcome: kitsu_core::RunOutcomeClass) {
        debug_assert!(!matches!(outcome, kitsu_core::RunOutcomeClass::Succeeded));
        self.primary_non_success.get_or_insert(outcome);
    }

    fn record_turn(
        &mut self,
        outcome: kitsu_core::RunOutcomeClass,
        assistant: kitsu_core::RunAssistantDisposition,
    ) {
        match outcome {
            kitsu_core::RunOutcomeClass::Succeeded => self.successful_operation = true,
            kitsu_core::RunOutcomeClass::PartiallySucceeded => {
                self.successful_operation = true;
                self.primary_non_success
                    .get_or_insert(kitsu_core::RunOutcomeClass::PartiallySucceeded);
            }
            other => self.record_non_success(other),
        }
        self.assistant = assistant;
    }

    fn record_replaced_turn(&mut self) {
        self.replaced_turns = self.replaced_turns.saturating_add(1);
        self.assistant = kitsu_core::RunAssistantDisposition::Discarded;
    }

    fn record_background_snapshot(&mut self, snapshot: &subagent::AgentProgressSnapshot) {
        self.successful_operation |= snapshot.done > 0;
        if snapshot.failed > 0 {
            self.primary_non_success
                .get_or_insert(kitsu_core::RunOutcomeClass::ProviderFault);
        }
        if snapshot.cancelled > 0 {
            self.primary_non_success
                .get_or_insert(kitsu_core::RunOutcomeClass::Cancelled);
        }
    }

    fn observe_cleanup(&mut self, cleanup: kitsu_core::RunCleanupState) {
        use kitsu_core::RunCleanupState::{Joined, NotObserved, Residue};
        self.cleanup = match (self.cleanup, cleanup) {
            (NotObserved, _) | (_, NotObserved) => NotObserved,
            (Joined, state) => state,
            (state, Joined) => state,
            (Residue { unjoined: left }, Residue { unjoined: right }) => Residue {
                unjoined: std::num::NonZeroU32::new(left.get().saturating_add(right.get()))
                    .expect("sum of nonzero cleanup residue remains nonzero"),
            },
        };
    }

    fn outcome(&self) -> kitsu_core::RunOutcomeClass {
        match (self.successful_operation, self.primary_non_success) {
            (true, Some(_)) => kitsu_core::RunOutcomeClass::PartiallySucceeded,
            (true, None) | (false, None) => kitsu_core::RunOutcomeClass::Succeeded,
            (false, Some(outcome)) => outcome,
        }
    }

    const fn assistant(&self) -> kitsu_core::RunAssistantDisposition {
        self.assistant
    }

    #[cfg(test)]
    const fn replaced_turns(&self) -> u32 {
        self.replaced_turns
    }

    fn terminal_facts(
        &self,
        persistence: kitsu_core::RunPersistenceState,
    ) -> InteractiveTerminalFacts {
        InteractiveTerminalFacts {
            outcome: self.outcome(),
            assistant: self.assistant(),
            cleanup: self.cleanup,
            persistence,
        }
    }
}

fn record_interactive_terminal_facts(facts: InteractiveTerminalFacts) -> Result<(), CliError> {
    PROCESS_INTERACTIVE_TERMINAL_FACTS
        .set(facts)
        .map_err(|_| CliError::user("interactive terminal facts were already recorded"))
}

fn record_process_terminal_facts_in(
    receipt: &OnceLock<ProcessTerminalFacts>,
    facts: ProcessTerminalFacts,
) -> Result<(), &'static str> {
    receipt
        .set(facts)
        .map_err(|_| "process terminal facts were already recorded")
}

fn record_process_terminal_facts(facts: ProcessTerminalFacts) -> Result<(), CliError> {
    record_process_terminal_facts_in(&PROCESS_TERMINAL_FACTS, facts).map_err(CliError::user)
}

fn process_terminal_facts_or_fallback() -> ProcessTerminalFacts {
    PROCESS_TERMINAL_FACTS
        .get()
        .copied()
        .unwrap_or(ProcessTerminalFacts {
            cleanup: if MODEL_INFERENCE_STARTED.load(Ordering::Acquire) {
                kitsu_core::RunCleanupState::NotObserved
            } else {
                kitsu_core::RunCleanupState::Joined
            },
            persistence: jsonl_session_persistence_state(),
        })
}

fn record_human_terminal_facts(cleanup: kitsu_core::RunCleanupState) -> Result<(), CliError> {
    record_process_terminal_facts(ProcessTerminalFacts {
        cleanup,
        persistence: jsonl_session_persistence_state(),
    })
}

fn record_human_terminal_facts_preserving_error(cleanup: kitsu_core::RunCleanupState) {
    if let Err(error) = record_human_terminal_facts(cleanup) {
        eprintln!("~ additional terminal fact handoff failure: {error}");
    }
}

fn run_elapsed() -> Duration {
    RUN_STARTED_AT.get_or_init(Instant::now).elapsed()
}

fn run_elapsed_ms() -> u64 {
    u64::try_from(run_elapsed().as_millis()).unwrap_or(u64::MAX)
}

fn record_successful_operation() {
    SUCCESSFUL_OPERATIONS.fetch_add(1, Ordering::AcqRel);
}

fn jsonl_emitter() -> &'static Mutex<kitsu_render::jsonl::JsonlEmitter<std::io::Stdout>> {
    static EMITTER: OnceLock<Mutex<kitsu_render::jsonl::JsonlEmitter<std::io::Stdout>>> =
        OnceLock::new();
    EMITTER.get_or_init(|| {
        Mutex::new(kitsu_render::jsonl::JsonlEmitter::new(
            std::io::stdout(),
            JSONL_SCHEMA,
            run_id(),
        ))
    })
}

fn emit_jsonl(kind: &str, payload: serde_json::Value) -> Result<(), CliError> {
    jsonl_emitter()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .emit(kind, payload)
        .map_err(CliError::jsonl_output)
}

fn jsonl_output_failure() -> Option<CliError> {
    jsonl_emitter()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .failure()
        .cloned()
        .map(CliError::jsonl_output)
}

/// Run-level counts of individual foreground tool-call errors. These are
/// deliberately separate from `*_failures`, which count failed requested
/// operations/turns. Policy errors are a subset of tool errors; recovered
/// errors belong to a turn that ultimately committed.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct ToolErrorTotals {
    tool_errors: u64,
    policy_errors: u64,
    recovered_tool_errors: u64,
    recovered_policy_errors: u64,
}

impl ToolErrorTotals {
    fn from_turn(status: &kitsu_core::AgentTurnStatus, recovered: bool) -> Self {
        let mut totals = Self::default();
        totals.record_turn(status, recovered);
        totals
    }

    fn record_turn(&mut self, status: &kitsu_core::AgentTurnStatus, recovered: bool) {
        let tool_errors = u64::from(status.tool_errors);
        let policy_errors = u64::from(status.policy_errors);
        debug_assert!(policy_errors <= tool_errors);
        self.tool_errors = self.tool_errors.saturating_add(tool_errors);
        self.policy_errors = self.policy_errors.saturating_add(policy_errors);
        if recovered {
            self.recovered_tool_errors = self.recovered_tool_errors.saturating_add(tool_errors);
            self.recovered_policy_errors =
                self.recovered_policy_errors.saturating_add(policy_errors);
        }
    }
}

fn emit_jsonl_summary(
    status: &str,
    failures: usize,
    provider_failures: usize,
) -> Result<(), CliError> {
    emit_jsonl_summary_with_local_failures(
        status,
        failures,
        provider_failures,
        0,
        0,
        0,
        ToolErrorTotals::default(),
    )
}

fn emit_jsonl_summary_with_local_failures(
    status: &str,
    failures: usize,
    provider_failures: usize,
    output_schema_failures: usize,
    tool_failures: usize,
    policy_failures: usize,
    tool_error_totals: ToolErrorTotals,
) -> Result<(), CliError> {
    emit_jsonl_summary_with_postcondition_failures(
        status,
        failures,
        provider_failures,
        output_schema_failures,
        0,
        tool_failures,
        policy_failures,
        tool_error_totals,
    )
}

fn jsonl_summary_outcome(
    status: &str,
    provider_failures: usize,
    tool_failures: usize,
    policy_failures: usize,
) -> Result<kitsu_core::RunOutcomeClass, CliError> {
    match status {
        "ok" => Ok(kitsu_core::RunOutcomeClass::Succeeded),
        "partial" => Ok(kitsu_core::RunOutcomeClass::PartiallySucceeded),
        "cancelled" => Ok(kitsu_core::RunOutcomeClass::Cancelled),
        "error" if provider_failures > 0 => Ok(kitsu_core::RunOutcomeClass::ProviderFault),
        "error" if tool_failures > 0 || policy_failures > 0 => {
            Ok(kitsu_core::RunOutcomeClass::ToolFault)
        }
        "error" => Ok(kitsu_core::RunOutcomeClass::UserFault),
        unknown => Err(CliError::user(format!(
            "internal final summary status is not recognized: {unknown}"
        ))),
    }
}

/// Run the deliberately narrow `ask --jsonl` terminal path through the common
/// lifecycle. `ask` has no tools/children or session store, making Joined and
/// NotRequested structural facts rather than carrier guesses. The delivery
/// closure is injectable so provider-free tests can cut the sink boundary.
#[cfg(test)]
fn finalize_terminal_with_delivery<E>(
    outcome: kitsu_core::RunOutcomeClass,
    assistant: kitsu_core::RunAssistantDisposition,
    cleanup: kitsu_core::RunCleanupState,
    persistence: kitsu_core::RunPersistenceState,
    deliver: impl FnOnce() -> Result<(), E>,
) -> Result<(kitsu_core::PublishedRun, Result<(), E>), kitsu_core::RunPhaseError> {
    let mut lifecycle = kitsu_core::RunLifecycle::accept(run_spec());
    finalize_owned_terminal_with_delivery(
        &mut lifecycle,
        outcome,
        assistant,
        cleanup,
        persistence,
        deliver,
    )
}

fn finalize_owned_terminal_with_delivery<E>(
    lifecycle: &mut kitsu_core::RunLifecycle,
    outcome: kitsu_core::RunOutcomeClass,
    assistant: kitsu_core::RunAssistantDisposition,
    cleanup: kitsu_core::RunCleanupState,
    persistence: kitsu_core::RunPersistenceState,
    deliver: impl FnOnce() -> Result<(), E>,
) -> Result<(kitsu_core::PublishedRun, Result<(), E>), kitsu_core::RunPhaseError> {
    lifecycle.settle(outcome, assistant)?;
    lifecycle.join(cleanup)?;
    lifecycle.persist(persistence)?;
    let delivery = deliver();
    lifecycle.deliver(if delivery.is_ok() {
        kitsu_core::RunDeliveryState::Delivered
    } else {
        kitsu_core::RunDeliveryState::Failed
    })?;
    let published = lifecycle.publish()?;
    Ok((published, delivery))
}

fn finalize_process_terminal_with_delivery<E>(
    outcome: kitsu_core::RunOutcomeClass,
    assistant: kitsu_core::RunAssistantDisposition,
    cleanup: kitsu_core::RunCleanupState,
    persistence: kitsu_core::RunPersistenceState,
    deliver: impl FnOnce() -> Result<(), E>,
) -> Result<(kitsu_core::PublishedRun, Result<(), E>), kitsu_core::RunPhaseError> {
    let mut lifecycle = process_run_lifecycle()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let result = finalize_owned_terminal_with_delivery(
        &mut lifecycle,
        outcome,
        assistant,
        cleanup,
        persistence,
        deliver,
    );
    if let Ok((published, _)) = &result {
        let recorded = PROCESS_PUBLISHED_RUN.set(published.clone());
        debug_assert!(recorded.is_ok(), "process terminal publication is unique");
    }
    result
}

#[cfg(test)]
fn finalize_ask_terminal_with_delivery<E>(
    outcome: kitsu_core::RunOutcomeClass,
    assistant: kitsu_core::RunAssistantDisposition,
    deliver: impl FnOnce() -> Result<(), E>,
) -> Result<(kitsu_core::PublishedRun, Result<(), E>), kitsu_core::RunPhaseError> {
    finalize_terminal_with_delivery(
        outcome,
        assistant,
        kitsu_core::RunCleanupState::Joined,
        kitsu_core::RunPersistenceState::NotRequested,
        deliver,
    )
}

#[allow(clippy::too_many_arguments)]
fn emit_ask_jsonl_summary_with_local_failures(
    status: &str,
    failures: usize,
    provider_failures: usize,
    output_schema_failures: usize,
    tool_failures: usize,
    policy_failures: usize,
    tool_error_totals: ToolErrorTotals,
) -> Result<(), CliError> {
    let outcome = jsonl_summary_outcome(status, provider_failures, tool_failures, policy_failures)?;
    let assistant = run_assistant_disposition();
    let (published, delivery) = finalize_process_terminal_with_delivery(
        outcome,
        assistant,
        kitsu_core::RunCleanupState::Joined,
        kitsu_core::RunPersistenceState::NotRequested,
        || {
            emit_jsonl_summary_with_local_failures(
                status,
                failures,
                provider_failures,
                output_schema_failures,
                tool_failures,
                policy_failures,
                tool_error_totals,
            )
        },
    )
    .map_err(|error| CliError::user(format!("internal ask finalization failed: {error}")))?;
    debug_assert_eq!(published.terminal().class(), outcome);
    debug_assert_eq!(published.terminal().assistant(), assistant);
    delivery
}

fn publish_fallback_inference_jsonl_terminal(error: &CliError) -> Result<(), CliError> {
    debug_assert!(MODEL_COMMAND_ACTIVE.load(Ordering::Acquire));
    let outcome = error.outcome_class();
    let assistant = run_assistant_disposition();
    let facts = process_terminal_facts_or_fallback();
    let cancelled = error.exit_code() == EXIT_CANCELLED;
    let (published, delivery) = finalize_process_terminal_with_delivery(
        outcome,
        assistant,
        facts.cleanup,
        facts.persistence,
        || {
            emit_jsonl("error", error.jsonl_error_payload())?;
            emit_jsonl_summary(
                if cancelled { "cancelled" } else { "error" },
                1,
                usize::from(error.exit_code() == EXIT_PROVIDER),
            )
        },
    )
    .map_err(|phase_error| {
        CliError::user(format!(
            "internal fallback inference finalization failed: {phase_error}"
        ))
    })?;
    debug_assert_eq!(published.terminal().class(), outcome);
    debug_assert_eq!(published.terminal().assistant(), assistant);
    debug_assert_eq!(published.cleanup(), facts.cleanup);
    debug_assert_eq!(published.persistence(), facts.persistence);
    delivery
}

fn publish_piped_jsonl_terminal(
    cleanup: kitsu_core::RunCleanupState,
    status: &str,
    provider_failures: usize,
    tool_failures: usize,
    policy_failures: usize,
    deliver: impl FnOnce() -> Result<(), CliError>,
) -> Result<(), CliError> {
    let outcome = jsonl_summary_outcome(status, provider_failures, tool_failures, policy_failures)?;
    let assistant = run_assistant_disposition();
    let persistence = jsonl_session_persistence_state();
    let (published, delivery) =
        finalize_process_terminal_with_delivery(outcome, assistant, cleanup, persistence, deliver)
            .map_err(|error| {
                CliError::user(format!("internal piped finalization failed: {error}"))
            })?;
    debug_assert_eq!(published.terminal().class(), outcome);
    debug_assert_eq!(published.terminal().assistant(), assistant);
    debug_assert_eq!(published.cleanup(), cleanup);
    debug_assert_eq!(published.persistence(), persistence);
    delivery
}

#[allow(clippy::too_many_arguments)]
fn emit_jsonl_summary_with_postcondition_failures(
    status: &str,
    failures: usize,
    provider_failures: usize,
    output_schema_failures: usize,
    postcondition_failures: usize,
    tool_failures: usize,
    policy_failures: usize,
    tool_error_totals: ToolErrorTotals,
) -> Result<(), CliError> {
    debug_assert!(output_schema_failures <= provider_failures);
    let outcome = jsonl_summary_outcome(status, provider_failures, tool_failures, policy_failures)?;
    let terminal = run_spec().terminal(outcome, run_assistant_disposition());
    let cancelled_failures = usize::from(status == "cancelled" && failures > 0);
    let user_failures = failures
        .saturating_sub(provider_failures + tool_failures + policy_failures + cancelled_failures);
    debug_assert!(postcondition_failures <= user_failures);
    let (session_id, session_snapshot_state) = {
        let receipt = JSONL_SESSION_RECEIPT
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        (receipt.terminal_id(), receipt.snapshot_state.as_str())
    };
    let mut payload = serde_json::json!({
        "status": status,
        "outcome": terminal.class().as_str(),
        "assistant": terminal.assistant().as_str(),
        "failures": failures,
        "provider_failures": provider_failures,
        "output_schema_failures": output_schema_failures,
        "postcondition_failures": postcondition_failures,
        "tool_failures": tool_failures,
        "policy_failures": policy_failures,
        "tool_errors": tool_error_totals.tool_errors,
        "policy_errors": tool_error_totals.policy_errors,
        "recovered_tool_errors": tool_error_totals.recovered_tool_errors,
        "recovered_policy_errors": tool_error_totals.recovered_policy_errors,
        "user_failures": user_failures,
        "cancelled_failures": cancelled_failures,
        "successful_operations": SUCCESSFUL_OPERATIONS.load(Ordering::Acquire),
        "duration_ms": run_elapsed_ms(),
        "session_id": session_id,
        "session_snapshot_state": session_snapshot_state,
    });
    if let Some(state) = output_last_message_summary_state(postcondition_failures) {
        payload["output_last_message_state"] = serde_json::json!(state);
    }
    emit_jsonl("final_summary", payload)?;
    JSONL_SUMMARY_EMITTED.store(true, Ordering::Release);
    Ok(())
}

fn output_last_message_preserved_without_commit() -> bool {
    OUTPUT_LAST_MESSAGE_REQUESTED.load(Ordering::Acquire)
        && !FULLY_COMMITTED_ASSISTANT_SEEN.load(Ordering::Acquire)
}

fn output_last_message_summary_state(postcondition_failures: usize) -> Option<&'static str> {
    if !OUTPUT_LAST_MESSAGE_REQUESTED.load(Ordering::Acquire) {
        None
    } else if !FULLY_COMMITTED_ASSISTANT_SEEN.load(Ordering::Acquire) {
        Some("preserved_no_committed_assistant")
    } else if postcondition_failures > 0 {
        Some("preserved_postcondition_failure")
    } else {
        None
    }
}

fn set_jsonl_session_receipt(planned_id: Option<String>, snapshot_state: SessionSnapshotState) {
    *JSONL_SESSION_RECEIPT
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner) =
        JsonlSessionReceipt::new(planned_id, snapshot_state);
}

fn mark_jsonl_session_resumable(session_id: &str) {
    JSONL_SESSION_RECEIPT
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .mark_committed(session_id);
}

fn mark_jsonl_session_persistence_failed() {
    JSONL_SESSION_RECEIPT
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .mark_failed();
}

fn jsonl_session_persistence_state() -> kitsu_core::RunPersistenceState {
    JSONL_SESSION_RECEIPT
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .persistence_state()
}

fn validate_output_last_message_surface(cli: &Cli) -> Result<(), CliError> {
    let Some(destination) = cli.output_last_message.as_deref() else {
        return Ok(());
    };
    let inference_surface = cli.print_prompt.is_some()
        || matches!(
            cli.command.as_ref(),
            None | Some(Command::Ask { .. })
                | Some(Command::Review { .. })
                | Some(Command::Chat { .. })
        );
    if !inference_surface {
        return Err(CliError::user(
            "--output-last-message is supported only by non-interactive ask, review, piped chat, and scripted chat"
                .to_string(),
        ));
    }
    if cli.jsonl && destination.to_str().is_none() {
        return Err(CliError::user(
            "--output-last-message PATH must be valid UTF-8 when combined with --jsonl".to_string(),
        ));
    }
    let interactive_surface = cli.print_prompt.is_none()
        && match cli.command.as_ref() {
            None => kitsu_render::stdin_is_tty(),
            Some(Command::Chat { script, .. }) => script.is_none() && kitsu_render::stdin_is_tty(),
            _ => false,
        };
    if interactive_surface {
        return Err(CliError::user(
            "--output-last-message is an automation mode; use --script, pipe one prompt, `ask`, or `review`"
                .to_string(),
        ));
    }
    session::validate_output_file_target(destination).map_err(CliError::user)
}

fn validate_output_schema_surface(cli: &Cli) -> Result<(), CliError> {
    let Some(path) = cli.output_schema.as_deref() else {
        return Ok(());
    };
    let inference_surface = cli.print_prompt.is_some()
        || matches!(
            cli.command.as_ref(),
            None | Some(Command::Ask { .. })
                | Some(Command::Review { .. })
                | Some(Command::Chat { .. })
        );
    if !inference_surface {
        return Err(CliError::user(
            "--output-schema is supported only by non-interactive ask, review, piped chat, and scripted chat"
                .to_string(),
        ));
    }
    let interactive_surface = cli.print_prompt.is_none()
        && match cli.command.as_ref() {
            None => kitsu_render::stdin_is_tty(),
            Some(Command::Chat { script, .. }) => script.is_none() && kitsu_render::stdin_is_tty(),
            _ => false,
        };
    if interactive_surface {
        return Err(CliError::user(
            "--output-schema is an automation mode; use --script, pipe one prompt, `ask`, or `review`"
                .to_string(),
        ));
    }
    let schema = structured_output::OutputSchema::load(path).map_err(CliError::user)?;
    OUTPUT_SCHEMA
        .set(schema)
        .map_err(|_| CliError::user("--output-schema was initialized more than once".to_string()))
}

fn inference_command_requested(cli: &Cli) -> bool {
    cli.print_prompt.is_some()
        || matches!(
            cli.command.as_ref(),
            None | Some(Command::Ask { .. })
                | Some(Command::Review { .. })
                | Some(Command::Chat { .. })
        )
}

fn inference_carrier(cli: &Cli, stdin_is_tty: bool) -> Option<InferenceCarrier> {
    let human_or_jsonl = |human, jsonl| if cli.jsonl { jsonl } else { human };
    if cli.print_prompt.is_some() {
        return Some(human_or_jsonl(
            InferenceCarrier::AskHuman,
            InferenceCarrier::AskJsonl,
        ));
    }
    match cli.command.as_ref() {
        Some(Command::Ask { .. }) => Some(human_or_jsonl(
            InferenceCarrier::AskHuman,
            InferenceCarrier::AskJsonl,
        )),
        Some(Command::Review { .. }) => Some(human_or_jsonl(
            InferenceCarrier::PipedHuman,
            InferenceCarrier::PipedJsonl,
        )),
        Some(Command::Chat {
            script: Some(_), ..
        }) => Some(human_or_jsonl(
            InferenceCarrier::ScriptHuman,
            InferenceCarrier::ScriptJsonl,
        )),
        None | Some(Command::Chat { script: None, .. }) if stdin_is_tty && !cli.jsonl => {
            Some(InferenceCarrier::InteractiveHuman)
        }
        None | Some(Command::Chat { script: None, .. }) => Some(human_or_jsonl(
            InferenceCarrier::PipedHuman,
            InferenceCarrier::PipedJsonl,
        )),
        _ => None,
    }
}

fn active_output_schema() -> Option<&'static structured_output::OutputSchema> {
    OUTPUT_SCHEMA.get()
}

fn emit_output_schema_receipt(cli: &Cli) -> Result<(), CliError> {
    let Some(schema) = active_output_schema() else {
        return Ok(());
    };
    if cli.jsonl {
        emit_jsonl(
            "output_schema",
            serde_json::json!({
                "name": "kitsu_output",
                "bytes": schema.bytes,
                "sha256": schema.sha256,
                "strict": true,
                "provider_format": "json_schema",
                "schema_preflight_validated": true,
                "local_validation": true,
                "schema_content_included": false,
                "model_file_authority": false,
            }),
        )?;
    } else {
        eprintln!(
            "~ structured output: strict JSON Schema ({} bytes, sha256 {})",
            schema.bytes, schema.sha256
        );
    }
    Ok(())
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RequiredWriteFingerprint {
    bytes: usize,
    sha256: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RequiredWriteContract {
    requested: String,
    resolved: std::path::PathBuf,
    initial: Option<RequiredWriteFingerprint>,
    expected_sha256: Option<String>,
}

struct RequiredWriteEvaluation {
    satisfied: bool,
    results: Vec<serde_json::Value>,
    failure: Option<CliError>,
}

fn required_write_fingerprint(
    path: &std::path::Path,
    perms: &Permissions,
) -> Result<Option<RequiredWriteFingerprint>, String> {
    let Some(bytes) =
        kitsu_tools::builtins::fs::read_verified_write_target(path, perms.max_write_bytes())
            .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    perms.check_write_size(bytes.len()).map_err(|error| {
        format!(
            "required-write target '{}' cannot be verified: {error}",
            path.display()
        )
    })?;
    Ok(Some(RequiredWriteFingerprint {
        bytes: bytes.len(),
        sha256: skills::content_sha256_hex(&bytes),
    }))
}

fn required_write_fingerprint_bytes(bytes: &[u8]) -> RequiredWriteFingerprint {
    RequiredWriteFingerprint {
        bytes: bytes.len(),
        sha256: skills::content_sha256_hex(bytes),
    }
}

async fn prepare_required_writes(
    requested_paths: &[String],
    requested_sha256: &[String],
    perms: &Permissions,
) -> Result<Vec<RequiredWriteContract>, CliError> {
    let mut requested_contracts = requested_paths
        .iter()
        .map(|requested| (requested.clone(), None, "--require-write"))
        .collect::<Vec<_>>();
    for encoded in requested_sha256 {
        let (requested, sha256) = parse_required_write_sha256(encoded)?;
        requested_contracts.push((requested, Some(sha256), "--require-write-sha256"));
    }

    let mut contracts: Vec<RequiredWriteContract> = Vec::with_capacity(requested_contracts.len());
    for (requested, expected_sha256, option) in requested_contracts {
        let resolved = perms
            .check_write(std::path::Path::new(&requested))
            .await
            .map_err(|error| {
                CliError::user(format!(
                    "{option} target '{}' has no active model filesystem write authority: {error}; add --allow-write or --allow-read-write for its parent",
                    requested
                ))
            })?;
        if let Some(existing) = contracts
            .iter_mut()
            .find(|contract| contract.resolved == resolved)
        {
            if let Some(expected_sha256) = expected_sha256 {
                match existing.expected_sha256.as_deref() {
                    Some(existing_sha256) if existing_sha256 != expected_sha256 => {
                        return Err(CliError::user(format!(
                            "conflicting --require-write-sha256 expectations for '{}': {existing_sha256} and {expected_sha256}",
                            resolved.display()
                        )));
                    }
                    Some(_) => {}
                    None => {
                        if existing
                            .initial
                            .as_ref()
                            .is_some_and(|initial| initial.sha256 == expected_sha256)
                        {
                            return Err(CliError::user(format!(
                                "--require-write-sha256 target '{}' already has the required SHA-256 {expected_sha256} at launch; the required-write contract also requires a final content change, so this expectation cannot be satisfied",
                                requested
                            )));
                        }
                        existing.expected_sha256 = Some(expected_sha256);
                    }
                }
            }
            continue;
        }
        let initial = required_write_fingerprint(&resolved, perms).map_err(CliError::user)?;
        if initial.is_some() {
            perms.check_read(&resolved).await.map_err(|error| {
                CliError::user(format!(
                    "{option} target '{}' already exists but has no active model filesystem read authority: {error}; existing targets need --allow-read-write for their parent (or matching --allow-path in addition to write authority), while --allow-write alone is only valid for creating a new file",
                    requested
                ))
            })?;
        }
        if let (Some(initial), Some(expected_sha256)) = (&initial, &expected_sha256) {
            if initial.sha256 == *expected_sha256 {
                return Err(CliError::user(format!(
                    "--require-write-sha256 target '{}' already has the required SHA-256 {expected_sha256} at launch; the required-write contract also requires a final content change, so this expectation cannot be satisfied",
                    requested
                )));
            }
        }
        contracts.push(RequiredWriteContract {
            requested,
            resolved,
            initial,
            expected_sha256,
        });
    }
    Ok(contracts)
}

fn parse_required_write_sha256(encoded: &str) -> Result<(String, String), CliError> {
    let Some((path, sha256)) = encoded.rsplit_once('=') else {
        return Err(CliError::user(
            "--require-write-sha256 expects PATH=SHA256 (PATH may contain '=')".to_string(),
        ));
    };
    if path.is_empty() {
        return Err(CliError::user(
            "--require-write-sha256 expects a non-empty PATH before the final '='".to_string(),
        ));
    }
    if sha256.len() != 64 || !sha256.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(CliError::user(
            "--require-write-sha256 expects exactly 64 hexadecimal SHA-256 characters after the final '='"
                .to_string(),
        ));
    }
    Ok((path.to_string(), sha256.to_ascii_lowercase()))
}

fn required_write_targets(contracts: &[RequiredWriteContract]) -> Vec<String> {
    contracts
        .iter()
        .map(|contract| contract.resolved.to_string_lossy().into_owned())
        .collect()
}

fn required_write_expectations(contracts: &[RequiredWriteContract]) -> Vec<serde_json::Value> {
    contracts
        .iter()
        .filter_map(|contract| {
            contract.expected_sha256.as_ref().map(|sha256| {
                serde_json::json!({
                    "path": contract.resolved.to_string_lossy(),
                    "sha256": sha256,
                })
            })
        })
        .collect()
}

fn required_write_system_instruction(contracts: &[RequiredWriteContract]) -> Option<String> {
    (!contracts.is_empty()).then(|| {
        let targets = serde_json::to_string(&required_write_targets(contracts))
            .expect("required-write path list serializes");
        let expectations = required_write_expectations(contracts);
        let exact = if expectations.is_empty() {
            String::new()
        } else {
            format!(
                " Exact raw-byte SHA-256 expectations are host-verified for this JSON array: {}.",
                serde_json::to_string(&expectations)
                    .expect("required-write SHA-256 expectations serialize")
            )
        };
        format!(
            "\n\n---\nHost-enforced completion postcondition: before your final response, use the filesystem tools to make a real content change to every path in this JSON array: {targets}.{exact} The paths already have explicit write authority; this instruction grants no additional authority. A final response is not successful unless Kitsu verifies both the model-tool write and a final state different from process launch, plus every declared exact SHA-256 expectation."
        )
    })
}

fn emit_required_write_armed(
    cli: &Cli,
    contracts: &[RequiredWriteContract],
) -> Result<(), CliError> {
    if contracts.is_empty() {
        return Ok(());
    }
    let targets = required_write_targets(contracts);
    let expectations = required_write_expectations(contracts);
    if cli.jsonl {
        emit_jsonl(
            "completion_postcondition",
            serde_json::json!({
                "phase": "armed",
                "condition": "required_write",
                "status": "pending",
                "targets": targets,
                "expectations": expectations,
                "results": [],
                "verification": "verified_model_fs_write_and_final_state_change",
                "model_disclosed": true,
                "write_authority_granted": false,
            }),
        )?;
    } else {
        eprintln!(
            "~ completion postcondition armed: {} required model-written file(s)",
            targets.len()
        );
    }
    Ok(())
}

/// Return a bounded, host-owned repair instruction only when a model write is
/// already journaled and its descriptor-pinned current bytes satisfy every
/// ordinary mutation invariant except an exact SHA-256 expectation. Missing
/// writes and unverifiable state remain the terminal postcondition's job; this
/// gate must never broaden authority or turn a run-level contract into an
/// eager per-turn failure.
fn required_write_structured_repair(
    contracts: &[RequiredWriteContract],
    journal: &kitsu_tools::builtins::fs::WriteJournal,
) -> Option<kitsu_core::StructuredFinalizationRepair> {
    let mut targets = Vec::new();
    for contract in contracts {
        let Some(expected_sha256) = contract.expected_sha256.as_ref() else {
            continue;
        };
        let Ok(Some((verification, Some(final_value)))) = journal
            .verify_written_path_with_current_content(&contract.resolved, |current| {
                current.map(required_write_fingerprint_bytes)
            })
        else {
            continue;
        };
        let final_state_changed = match &contract.initial {
            None => true,
            Some(initial) => initial != &final_value,
        };
        if verification.net_content_changed
            && verification.current_matches_latest_write
            && final_state_changed
            && final_value.sha256 != *expected_sha256
        {
            targets.push(kitsu_core::StructuredFinalizationRepairTarget {
                path: contract.resolved.to_string_lossy().into_owned(),
                expected_sha256: expected_sha256.clone(),
                actual_sha256: final_value.sha256,
            });
        }
    }
    if targets.is_empty() {
        return None;
    }
    targets.sort_by(|left, right| left.path.cmp(&right.path));
    let disclosed_targets =
        serde_json::to_string(&targets).expect("structured-finalization repair targets serialize");
    Some(kitsu_core::StructuredFinalizationRepair {
        cause: "required_write_sha256_mismatch".to_string(),
        instruction: format!(
            "Kitsu verified that the latest filesystem write does not yet match the required raw-byte SHA-256. Keep working with the available filesystem tools before answering. Correct these targets exactly: {disclosed_targets}. Do not give a final answer until every digest matches. This instruction grants no additional authority."
        ),
        targets,
    })
}

fn evaluate_required_writes(
    contracts: &[RequiredWriteContract],
    perms: &Permissions,
    journal: &kitsu_tools::builtins::fs::WriteJournal,
) -> RequiredWriteEvaluation {
    if contracts.is_empty() {
        return RequiredWriteEvaluation {
            satisfied: true,
            results: Vec::new(),
            failure: None,
        };
    }
    let mut results = Vec::with_capacity(contracts.len());
    let mut failures = Vec::new();
    for contract in contracts {
        let journal_verification = journal
            .verify_written_path_with_current_content(&contract.resolved, |current| {
                current.map(required_write_fingerprint_bytes)
            });
        let (
            journal_recorded,
            journal_net_change,
            current_matches,
            journal_error,
            final_value,
            final_error,
        ) = match journal_verification {
            Ok(Some((verification, final_value))) => (
                true,
                verification.net_content_changed,
                verification.current_matches_latest_write,
                None,
                final_value,
                None,
            ),
            Ok(None) => match required_write_fingerprint(&contract.resolved, perms) {
                Ok(value) => (false, false, false, None, value, None),
                Err(error) => (false, false, false, None, None, Some(error)),
            },
            Err(error) => (false, false, false, Some(error.to_string()), None, None),
        };
        let final_state_changed = match (&contract.initial, &final_value) {
            (None, Some(_)) => true,
            (Some(initial), Some(final_value)) => initial != final_value,
            _ => false,
        };
        let expected_sha256_matches = contract.expected_sha256.as_ref().map(|expected| {
            final_value
                .as_ref()
                .is_some_and(|final_value| final_value.sha256 == *expected)
        });
        let satisfied = journal_recorded
            && journal_net_change
            && current_matches
            && final_state_changed
            && final_error.is_none()
            && expected_sha256_matches != Some(false);
        let reason = if satisfied {
            None
        } else if let Some(error) = journal_error.as_deref() {
            Some(error.to_string())
        } else if let Some(error) = final_error.as_deref() {
            Some(error.to_string())
        } else if !journal_recorded {
            Some("no verified model filesystem write was recorded".to_string())
        } else if !journal_net_change || !final_state_changed {
            Some("final file contents do not differ from process launch".to_string())
        } else if !current_matches {
            Some("current file no longer matches the latest verified model write".to_string())
        } else if expected_sha256_matches == Some(false) {
            Some(format!(
                "final raw-byte SHA-256 {} does not match required {}",
                final_value
                    .as_ref()
                    .map_or("missing", |value| value.sha256.as_str()),
                contract
                    .expected_sha256
                    .as_deref()
                    .expect("mismatch requires an exact expectation")
            ))
        } else {
            Some("required write could not be verified".to_string())
        };
        if let Some(reason) = reason.as_ref() {
            failures.push(format!("{} ({reason})", contract.requested));
        }
        results.push(serde_json::json!({
            "path": contract.resolved.to_string_lossy(),
            "requested_path": contract.requested,
            "satisfied": satisfied,
            "journal_recorded": journal_recorded,
            "journal_net_content_changed": journal_net_change,
            "current_matches_latest_write": current_matches,
            "final_state_changed": final_state_changed,
            "initial_bytes": contract.initial.as_ref().map(|value| value.bytes),
            "initial_sha256": contract.initial.as_ref().map(|value| value.sha256.as_str()),
            "final_bytes": final_value.as_ref().map(|value| value.bytes),
            "final_sha256": final_value.as_ref().map(|value| value.sha256.as_str()),
            "expected_sha256": contract.expected_sha256.as_deref(),
            "expected_sha256_matches": expected_sha256_matches,
            "reason": reason,
        }));
    }
    let satisfied = failures.is_empty();
    let failure = (!satisfied).then(|| {
        CliError::user(format!(
            "completion postcondition failed: required write contract was not satisfied for {}",
            failures.join(", ")
        ))
    });
    RequiredWriteEvaluation {
        satisfied,
        results,
        failure,
    }
}

fn emit_required_write_evaluation(
    cli: &Cli,
    contracts: &[RequiredWriteContract],
    evaluation: &RequiredWriteEvaluation,
) -> Result<(), CliError> {
    if contracts.is_empty() {
        return Ok(());
    }
    if cli.jsonl {
        let expectations = required_write_expectations(contracts);
        emit_jsonl(
            "completion_postcondition",
            serde_json::json!({
                "phase": "evaluated",
                "condition": "required_write",
                "status": if evaluation.satisfied { "satisfied" } else { "failed" },
                "targets": required_write_targets(contracts),
                "expectations": expectations,
                "results": evaluation.results,
                "verification": "verified_model_fs_write_and_final_state_change",
                "model_disclosed": true,
                "write_authority_granted": false,
            }),
        )?;
    } else if evaluation.satisfied {
        eprintln!(
            "~ completion postcondition satisfied: {} required model-written file(s) verified",
            contracts.len()
        );
    } else if let Some(error) = evaluation.failure.as_ref() {
        eprintln!("~ {}", terminal_inline(&error.to_string()));
    }
    Ok(())
}

fn emit_required_write_error(cli: &Cli, error: &CliError) -> Result<(), CliError> {
    if cli.jsonl {
        emit_jsonl(
            "error",
            serde_json::json!({
                "kind": "postcondition",
                "condition": "required_write",
                "message": error.to_string(),
                "exit_code": error.exit_code(),
            }),
        )?;
    }
    Ok(())
}

fn reject_host_file_command_authority(
    path: &std::path::Path,
    option: &str,
    purpose: &str,
    writable_roots: &[std::path::PathBuf],
    readonly_runtime_roots: &[std::path::PathBuf],
) -> Result<(), CliError> {
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| std::path::Path::new("."));
    let name = path.file_name().ok_or_else(|| {
        CliError::user(format!(
            "{option} {purpose} '{}' has no filename",
            path.display()
        ))
    })?;
    let canonical_parent = std::fs::canonicalize(parent).map_err(|error| {
        CliError::user(format!(
            "cannot resolve {option} parent '{}': {error}",
            parent.display()
        ))
    })?;
    let canonical_target = canonical_parent.join(name);

    for (roots, label) in [
        (writable_roots, "writable command root"),
        (readonly_runtime_roots, "read-only command runtime root"),
    ] {
        if let Some(root) = roots.iter().find(|root| canonical_target.starts_with(root)) {
            return Err(CliError::user(format!(
                "{option} {purpose} '{}' is visible inside {label} '{}'; choose a separate host-owned path outside command authority",
                path.display(),
                root.display()
            )));
        }
    }

    #[cfg(unix)]
    if let Ok(metadata) = std::fs::symlink_metadata(&canonical_target) {
        use std::os::unix::fs::MetadataExt as _;
        if metadata.nlink() > 1 {
            return Err(CliError::user(format!(
                "{option} {purpose} '{}' has multiple hard links while command tools are enabled; choose a single-link host-owned file",
                path.display()
            )));
        }
    }
    Ok(())
}

fn reject_host_output_command_authority(
    cli: &Cli,
    writable_roots: &[std::path::PathBuf],
    readonly_runtime_roots: &[std::path::PathBuf],
) -> Result<(), CliError> {
    if let Some(destination) = cli.output_last_message.as_deref() {
        reject_host_file_command_authority(
            destination,
            "--output-last-message",
            "destination",
            writable_roots,
            readonly_runtime_roots,
        )?;
    }
    if let Some(schema) = cli.output_schema.as_deref() {
        reject_host_file_command_authority(
            schema,
            "--output-schema",
            "file",
            writable_roots,
            readonly_runtime_roots,
        )?;
    }
    Ok(())
}

fn write_output_last_message(cli: &Cli, turn_id: &str, text: &str) -> Result<(), CliError> {
    let Some(destination) = cli.output_last_message.as_deref() else {
        return Ok(());
    };
    if let Err(error) = session::atomic_write_output_file(destination, text.as_bytes()) {
        let installed = error.installed;
        return Err(CliError::user(format!(
            "failed to write --output-last-message '{}': {error}{}",
            destination.display(),
            if installed {
                "; the exact message was installed, but durability could not be confirmed"
            } else {
                "; the destination was left unchanged"
            }
        )));
    }
    if cli.jsonl {
        emit_jsonl(
            "output_last_message",
            serde_json::json!({
                "turn_id": turn_id,
                "destination": destination
                    .to_str()
                    .expect("JSONL output destination validated as UTF-8"),
                "bytes": text.len(),
                "sha256": skills::content_sha256_hex(text.as_bytes()),
                "atomic": true,
                "assistant_committed": true,
                "content_included": false,
                "model_write_authority": false,
            }),
        )?;
    } else {
        eprintln!(
            "~ saved last committed assistant message to {} ({} bytes, atomic)",
            terminal_inline(&destination.display().to_string()),
            text.len(),
        );
    }
    Ok(())
}

fn emit_output_last_message_error(
    cli: &Cli,
    turn_id: &str,
    error: &CliError,
) -> Result<(), CliError> {
    if cli.jsonl {
        emit_jsonl(
            "error",
            serde_json::json!({
                "turn_id": turn_id,
                "kind": "output_last_message",
                "message": error.to_string(),
                "exit_code": error.exit_code(),
            }),
        )?;
    }
    Ok(())
}

/// Exit status when the process that was reading kitsu's output went away
/// first. Nothing failed on kitsu's side, and `cmd | head -1` is an everyday
/// shell idiom, so this mirrors the Unix convention of a quiet success.
const EXIT_BROKEN_PIPE: i32 = 0;

/// True for the panic Rust's print macros raise when the reader closed the
/// pipe. Message-shaped by necessity: `std` gives the hook no typed I/O error.
fn panic_payload_is_broken_pipe(payload: &str) -> bool {
    payload.starts_with("failed printing to std")
        && (payload.contains("Broken pipe") || payload.contains("os error 32"))
}

/// Rust masks `SIGPIPE` at startup, so a closed stdout turns every `println!`
/// into a panic and exit 101 — a code reserved for a real crash and absent from
/// kitsu's documented taxonomy (`kitsu sessions | head -1` hit it). The masking
/// is still wanted: the JSONL sink depends on seeing `BrokenPipe` as an error so
/// it can exit typed instead of dying by signal. So the panic is intercepted
/// here rather than the signal disposition being restored: a broken output pipe
/// stops the process quietly, everything else keeps the normal panic report.
fn install_broken_pipe_guard() {
    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let payload = info
            .payload()
            .downcast_ref::<String>()
            .map(String::as_str)
            .or_else(|| info.payload().downcast_ref::<&str>().copied())
            .unwrap_or_default();
        if panic_payload_is_broken_pipe(payload) {
            std::process::exit(EXIT_BROKEN_PIPE);
        }
        default_hook(info);
    }));
}

fn main() {
    let _ = RUN_STARTED_AT.set(Instant::now());
    // Every surface receives one neutral identity before argument parsing can
    // accept work. JSONL, human mode, and private artifacts then refer to the
    // same process-run spec even when presentation does not yet display it.
    let _ = run_spec();
    install_broken_pipe_guard();
    let jsonl_mode = jsonl_requested();
    // Logs (never the token: HeaderValue is marked sensitive) go to stderr.
    // JSONL owns both output channels: stdout is framed events and routine
    // diagnostics are suppressed so automation never has to scrape stderr.
    let trace_writer = if jsonl_mode {
        tracing_subscriber::fmt::writer::BoxMakeWriter::new(std::io::sink)
    } else {
        tracing_subscriber::fmt::writer::BoxMakeWriter::new(std::io::stderr)
    };
    let _ = tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("warn")),
        )
        .with_writer(trace_writer)
        .try_init();

    let (mut code, mut outcome_class) = match run() {
        Ok(()) if jsonl_mode => {
            jsonl_output_failure().map_or((0, kitsu_core::RunOutcomeClass::Succeeded), |error| {
                std::eprintln!("{error}");
                (error.exit_code(), error.outcome_class())
            })
        }
        Ok(()) => (
            0,
            if SCRIPT_ACCEPTED_PARTIAL.load(Ordering::Acquire) {
                kitsu_core::RunOutcomeClass::PartiallySucceeded
            } else {
                kitsu_core::RunOutcomeClass::Succeeded
            },
        ),
        Err(e) => {
            let outcome_class = e.outcome_class();
            let code = if !jsonl_mode {
                // One weighted `! error:` notice (ember-red on a TTY); any
                // extra lines in the message are the actionable hint.
                for line in kitsu_render::error_lines(&e.to_string()) {
                    std::eprintln!("{line}");
                }
                e.exit_code()
            } else {
                if !JSONL_SUMMARY_EMITTED.load(Ordering::Acquire) {
                    let frame_result = if MODEL_COMMAND_ACTIVE.load(Ordering::Acquire) {
                        // Carrier-provided facts win. Before the first provider
                        // turn, Joined is structural; after it, missing cleanup
                        // evidence is explicitly NotObserved rather than guessed.
                        publish_fallback_inference_jsonl_terminal(&e)
                    } else if jsonl_output_failure().is_none() {
                        let cancelled = e.exit_code() == EXIT_CANCELLED;
                        emit_jsonl("error", e.jsonl_error_payload()).and_then(|()| {
                            emit_jsonl_summary(
                                if cancelled { "cancelled" } else { "error" },
                                1,
                                usize::from(e.exit_code() == EXIT_PROVIDER),
                            )
                        })
                    } else {
                        Err(jsonl_output_failure()
                            .expect("management fallback observed terminal output failure"))
                    };
                    // `jsonl_output_failure` below reports the retained
                    // terminal error exactly once when framing itself fails.
                    let _ = frame_result;
                }
                jsonl_output_failure().map_or_else(
                    || e.exit_code(),
                    |output_error| {
                        // Framing is impossible after a terminal write/flush
                        // failure, so this is the one JSONL-mode stderr diagnostic.
                        std::eprintln!("{output_error}");
                        output_error.exit_code()
                    },
                )
            };
            (code, outcome_class)
        }
    };
    if jsonl_mode && MODEL_COMMAND_ACTIVE.load(Ordering::Acquire) {
        match (
            PROCESS_INFERENCE_CARRIER.get().copied(),
            PROCESS_PUBLISHED_RUN.get(),
        ) {
            (Some(carrier), Some(published)) => {
                code = evaluate_process_exit(code, carrier, published);
            }
            _ if code == 0 => {
                std::eprintln!("internal JSONL inference lifecycle was not published");
                code = EXIT_USER;
            }
            _ => {}
        }
    }
    if !jsonl_mode && output_last_message_preserved_without_commit() {
        std::eprintln!("~ --output-last-message unchanged: no committed assistant message");
    }
    if !jsonl_mode && MODEL_COMMAND_ACTIVE.load(Ordering::Acquire) {
        let interactive_facts = PROCESS_INTERACTIVE_TERMINAL_FACTS.get().copied();
        if let Some(facts) = interactive_facts {
            outcome_class = facts.outcome;
        }
        let terminal = run_spec().terminal(
            outcome_class,
            interactive_facts.map_or_else(run_assistant_disposition, |facts| facts.assistant),
        );
        let status = match terminal.class() {
            kitsu_core::RunOutcomeClass::Succeeded => kitsu_render::RunTimingStatus::Ok,
            kitsu_core::RunOutcomeClass::PartiallySucceeded => {
                kitsu_render::RunTimingStatus::Partial
            }
            kitsu_core::RunOutcomeClass::Cancelled => kitsu_render::RunTimingStatus::Cancelled,
            kitsu_core::RunOutcomeClass::Interrupted => kitsu_render::RunTimingStatus::Interrupted,
            kitsu_core::RunOutcomeClass::UserFault
            | kitsu_core::RunOutcomeClass::ProviderFault
            | kitsu_core::RunOutcomeClass::ToolFault => kitsu_render::RunTimingStatus::Error,
        };
        let deliver = || {
            kitsu_render::emit_run_timing(
                run_elapsed(),
                status,
                kitsu_render::HumanRunReceipt {
                    run_id: terminal.run_id().as_str(),
                    outcome: terminal.class().as_str(),
                    assistant: terminal.assistant().as_str(),
                },
            )
        };
        let facts = interactive_facts.map_or_else(process_terminal_facts_or_fallback, |facts| {
            ProcessTerminalFacts {
                cleanup: facts.cleanup,
                persistence: facts.persistence,
            }
        });
        match finalize_process_terminal_with_delivery(
            terminal.class(),
            terminal.assistant(),
            facts.cleanup,
            facts.persistence,
            deliver,
        ) {
            Ok((published, delivery)) => {
                debug_assert_eq!(published.terminal(), &terminal);
                debug_assert_eq!(
                    delivery.is_ok(),
                    published.delivery() == kitsu_core::RunDeliveryState::Delivered
                );
                let carrier = PROCESS_INFERENCE_CARRIER
                    .get()
                    .copied()
                    .expect("active model command has an inference carrier");
                code = evaluate_process_exit(code, carrier, &published);
            }
            Err(error) => {
                std::eprintln!("internal human inference finalization failed: {error}");
                if code == 0 {
                    code = EXIT_USER;
                }
            }
        }
    }
    std::process::exit(code);
}

/// Top-level error carrying the right exit code.
struct CliError {
    message: String,
    code: i32,
    diagnostic: Option<ProviderDiagnosticCode>,
    outcome_class: kitsu_core::RunOutcomeClass,
}

impl CliError {
    fn user(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            code: EXIT_USER,
            diagnostic: None,
            outcome_class: kitsu_core::RunOutcomeClass::UserFault,
        }
    }
    fn provider(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            code: EXIT_PROVIDER,
            diagnostic: None,
            outcome_class: kitsu_core::RunOutcomeClass::ProviderFault,
        }
    }
    fn cancelled(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            code: EXIT_CANCELLED,
            diagnostic: None,
            outcome_class: kitsu_core::RunOutcomeClass::Cancelled,
        }
    }

    fn tool(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            code: EXIT_USER,
            diagnostic: None,
            outcome_class: kitsu_core::RunOutcomeClass::ToolFault,
        }
    }

    fn interrupted(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            code: EXIT_USER,
            diagnostic: None,
            outcome_class: kitsu_core::RunOutcomeClass::Interrupted,
        }
    }

    fn with_diagnostic(mut self, diagnostic: Option<ProviderDiagnosticCode>) -> Self {
        self.diagnostic = diagnostic;
        self
    }

    fn jsonl_output(error: kitsu_render::jsonl::JsonlEmitError) -> Self {
        Self::user(format!("JSONL output failed: {error}"))
    }
    fn exit_code(&self) -> i32 {
        self.code
    }

    fn outcome_class(&self) -> kitsu_core::RunOutcomeClass {
        self.outcome_class
    }

    fn jsonl_kind(&self) -> &'static str {
        match self.code {
            EXIT_PROVIDER => "provider",
            EXIT_CANCELLED => "cancelled",
            _ => "user",
        }
    }

    fn jsonl_error_payload(&self) -> serde_json::Value {
        let mut payload = serde_json::json!({
            "kind": self.jsonl_kind(),
            "message": self.to_string(),
            "exit_code": self.exit_code(),
        });
        if let Some(diagnostic) = self.diagnostic {
            payload["diagnostic_code"] = serde_json::json!(diagnostic.code());
            payload["recovery_actions"] = serde_json::json!(diagnostic.recovery_actions());
        }
        payload
    }
}

impl From<RegistryError> for CliError {
    fn from(error: RegistryError) -> Self {
        Self::user(format!("tool registry composition failed: {error}"))
    }
}

impl std::fmt::Display for CliError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", kitsu_render::sanitize_terminal_text(&self.message))
    }
}

fn run() -> Result<(), CliError> {
    let cli = match Cli::try_parse() {
        Ok(cli) => cli,
        Err(error) => match error.kind() {
            clap::error::ErrorKind::DisplayHelp | clap::error::ErrorKind::DisplayVersion => {
                if jsonl_requested() {
                    return Err(CliError::user(
                        "--jsonl cannot be combined with human --help or --version output",
                    ));
                }
                // `kitsu --help | head -3` closes the pipe mid-help. That is the
                // reader's choice, not a kitsu failure; every other write error
                // still reports.
                return match error.print() {
                    Ok(()) => Ok(()),
                    Err(e) if e.kind() == std::io::ErrorKind::BrokenPipe => Ok(()),
                    Err(e) => Err(CliError::user(format!("failed to print command help: {e}"))),
                };
            }
            _ => return Err(CliError::user(error.to_string())),
        },
    };
    kitsu_render::configure_terminal_modes(cli.plain, cli.reduced_motion, cli.screen_reader);
    if inference_command_requested(&cli) {
        // Accept the process lifecycle before output/config/runtime preflight,
        // not only after a carrier has successfully built its provider.
        let carrier = inference_carrier(&cli, kitsu_render::stdin_is_tty())
            .expect("every inference command has an explicit carrier");
        activate_model_command(carrier)?;
    }
    validate_output_last_message_surface(&cli)?;
    OUTPUT_LAST_MESSAGE_REQUESTED.store(cli.output_last_message.is_some(), Ordering::Release);
    validate_output_schema_surface(&cli)?;

    let runtime = tokio::runtime::Runtime::new()
        .map_err(|e| CliError::user(format!("failed to start runtime: {e}")))?;

    if let Some(prompt) = cli.print_prompt.as_deref() {
        if cli.command.is_some() {
            return Err(CliError::user(
                "-p/--prompt is a top-level one-shot mode and cannot be combined with a subcommand; use `kitsu -p <PROMPT>` or the subcommand's own prompt argument",
            ));
        }
        return runtime.block_on(run_ask(&cli, prompt));
    }

    match cli.command.as_ref() {
        None => runtime.block_on(run_chat(&cli, ChatInvocation::default())),
        Some(Command::Init { path, json }) => run_init(&cli, path.as_deref(), *json),
        Some(Command::Doctor {
            online,
            inference,
            json,
        }) => runtime.block_on(run_doctor(&cli, *online, *inference, *json)),
        Some(Command::Auth { json, command }) => runtime.block_on(run_auth(&cli, *json, command)),
        Some(Command::Ask { prompt }) => runtime.block_on(run_ask(&cli, prompt)),
        Some(Command::Review {
            path,
            staged,
            unstaged,
            base,
            commit,
            instructions,
            resume,
            session,
        }) => {
            let scope = if *staged {
                ReviewScope::Staged
            } else if *unstaged {
                ReviewScope::Unstaged
            } else if let Some(revision) = base {
                ReviewScope::Base(revision.clone())
            } else if let Some(revision) = commit {
                ReviewScope::Commit(revision.clone())
            } else {
                ReviewScope::Working
            };
            runtime.block_on(run_review(
                &cli,
                InitialReview {
                    request: ReviewRequest {
                        scope,
                        path: path.clone(),
                    },
                    instructions: instructions.clone(),
                },
                resume.as_deref(),
                *session,
            ))
        }
        Some(Command::Models { filter }) => {
            runtime.block_on(run_models(&cli, filter.as_deref().unwrap_or("")))
        }
        Some(Command::Sessions { json, command }) => {
            runtime.block_on(run_sessions(&cli, *json, command.as_ref()))
        }
        Some(Command::Artifacts { json, command }) => run_artifacts(&cli, *json, command.as_ref()),
        Some(Command::Agents { json, all }) => run_agents(&cli, *json, *all),
        Some(Command::Chat {
            prompt,
            no_tools,
            allow_paths,
            allow_write,
            allow_read_write,
            require_writes,
            require_write_sha256,
            enable_commands,
            command_roots,
            command_runtime_roots,
            command_env,
            allow_commands,
            script,
            resume,
            session,
            no_session,
            name,
            allow_turn_errors,
        }) => runtime.block_on(run_chat(
            &cli,
            ChatInvocation {
                first_prompt: prompt.as_deref(),
                no_tools: *no_tools,
                allow_paths,
                allow_write,
                allow_read_write,
                require_writes,
                require_write_sha256,
                enable_commands: *enable_commands,
                command_roots,
                command_runtime_roots,
                command_env,
                allow_commands,
                script: script.as_deref(),
                resume: resume.as_deref(),
                persist_session: *session,
                no_session: *no_session,
                session_name: name.as_deref(),
                allow_turn_errors: *allow_turn_errors,
                initial_review: None,
            },
        )),
    }
}

#[derive(Default)]
struct ChatInvocation<'a> {
    first_prompt: Option<&'a str>,
    no_tools: bool,
    allow_paths: &'a [String],
    allow_write: &'a [String],
    allow_read_write: &'a [String],
    require_writes: &'a [String],
    require_write_sha256: &'a [String],
    enable_commands: bool,
    command_roots: &'a [String],
    command_runtime_roots: &'a [String],
    command_env: &'a [String],
    allow_commands: &'a [String],
    script: Option<&'a str>,
    resume: Option<&'a str>,
    persist_session: bool,
    no_session: bool,
    session_name: Option<&'a str>,
    allow_turn_errors: bool,
    initial_review: Option<InitialReview>,
}

#[derive(Clone)]
struct InitialReview {
    request: ReviewRequest,
    instructions: Option<String>,
}

async fn run_review(
    cli: &Cli,
    review: InitialReview,
    resume: Option<&str>,
    persist_session: bool,
) -> Result<(), CliError> {
    // No fabricated read root. `kitsu review` gathers its evidence through the
    // host-owned WorkspaceEvidenceAuthority, so granting the model the whole
    // repository would be an undisclosed invocation read root that buys nothing.
    run_chat(
        cli,
        ChatInvocation {
            first_prompt: None,
            no_tools: false,
            allow_paths: &[],
            allow_write: &[],
            allow_read_write: &[],
            require_writes: &[],
            require_write_sha256: &[],
            enable_commands: false,
            command_roots: &[],
            command_runtime_roots: &[],
            command_env: &[],
            allow_commands: &[],
            script: None,
            resume,
            persist_session,
            no_session: false,
            session_name: None,
            allow_turn_errors: false,
            initial_review: Some(review),
        },
    )
    .await
}

// Kept byte-for-byte aligned with README's "Ollama (local)" provider recipe
// (flavor, base_url, and model) so `kitsu init` never disagrees with the
// docs a new user is reading one section away, and so the generated config
// works out of the box against `ollama pull llama3.2` without a model-tag
// mismatch (cycle-8 docs-drift finding: the old `qwen2.5-coder:7b` default
// 404'd against the tag Ollama actually produces). `flavor` is validated
// against a closed set (`openai`/`anthropic`/`ollama`) but every value
// currently routes through the same OpenAI-compatible transport — `openai`
// here matches every other recipe, including this same Ollama gateway.
const STARTER_CONFIG_BODY: &str = r#"default_gateway = "ollama"
# Optional privacy default: create no automatic command/tool-output artifacts.
# artifact_storage = false

[gateways.ollama]
flavor = "openai"
base_url = "http://localhost:11434"
chat_path = "/v1/chat/completions"
models_path = "/v1/models"
# Pull this model first (ollama pull llama3.2) or set one you already have
model = "llama3.2"
context_window = 32768
auth = { method = "none" }
"#;

fn starter_config(destination: &std::path::Path) -> String {
    format!(
        "# Kitsu starter configuration (contains no credentials).\n# Next: kitsu --config {} doctor\n{STARTER_CONFIG_BODY}",
        shell_quote(&destination.to_string_lossy()),
    )
}

/// Infer the export format from the destination extension. Only `.json` (case
/// insensitively) selects JSON; everything else keeps the Markdown default, so
/// the inference can never surprise an existing `.md`/extensionless workflow.
fn inferred_export_format(destination: &std::path::Path) -> session::SessionExportFormat {
    let is_json = destination
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("json"));
    if is_json {
        session::SessionExportFormat::Json
    } else {
        session::SessionExportFormat::Markdown
    }
}

fn reject_jsonl_for_management(cli: &Cli, replacement: &str) -> Result<(), CliError> {
    if cli.jsonl {
        Err(CliError::user(format!(
            "--jsonl is reserved for chat automation events; use {replacement} for this command"
        )))
    } else {
        Ok(())
    }
}

/// True when an output failure is only "the reader stopped reading". A closed
/// consumer (`| head -1`) is a normal shell idiom, not a kitsu error, and must
/// not be reported as one. The JSONL event sink keeps its own stricter contract.
fn output_error_is_broken_pipe(error: &std::io::Error) -> bool {
    error.kind() == std::io::ErrorKind::BrokenPipe
}

fn print_json<T: serde::Serialize>(value: &T) -> Result<(), CliError> {
    use std::io::Write as _;
    let mut stdout = std::io::stdout().lock();
    if let Err(error) = serde_json::to_writer_pretty(&mut stdout, value) {
        if error.io_error_kind() == Some(std::io::ErrorKind::BrokenPipe) {
            return Ok(());
        }
        return Err(CliError::user(format!(
            "failed to encode JSON output: {error}"
        )));
    }
    if let Err(error) = stdout.write_all(b"\n") {
        if output_error_is_broken_pipe(&error) {
            return Ok(());
        }
        return Err(CliError::user(format!("failed to write output: {error}")));
    }
    match stdout.flush() {
        Ok(()) => Ok(()),
        Err(error) if output_error_is_broken_pipe(&error) => Ok(()),
        Err(error) => Err(CliError::user(format!("failed to flush output: {error}"))),
    }
}

fn run_init(cli: &Cli, requested: Option<&std::path::Path>, json: bool) -> Result<(), CliError> {
    use std::io::Write as _;

    reject_jsonl_for_management(cli, "kitsu init --json")?;
    let destination = requested
        .map(std::path::Path::to_path_buf)
        .or_else(|| cli.config.as_deref().map(std::path::PathBuf::from))
        .unwrap_or_else(|| std::path::PathBuf::from("kitsu.toml"));
    if let Some(parent) = destination
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent).map_err(|error| {
            CliError::user(format!(
                "cannot create config directory '{}': {error}",
                parent.display()
            ))
        })?;
    }

    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600).custom_flags(libc::O_NOFOLLOW);
    }
    let mut file = options.open(&destination).map_err(|error| {
        let detail = if error.kind() == std::io::ErrorKind::AlreadyExists {
            "already exists; refusing to overwrite it".to_string()
        } else {
            error.to_string()
        };
        CliError::user(format!(
            "cannot initialize config '{}': {detail}",
            destination.display()
        ))
    })?;
    let contents = starter_config(&destination);
    let write_result = file
        .write_all(contents.as_bytes())
        .and_then(|()| file.flush())
        .and_then(|()| file.sync_all());
    if let Err(error) = write_result {
        drop(file);
        let cleanup = std::fs::remove_file(&destination);
        let cleanup_note = cleanup
            .err()
            .map(|cleanup| format!("; partial file cleanup also failed: {cleanup}"))
            .unwrap_or_default();
        return Err(CliError::user(format!(
            "cannot write config '{}': {error}{cleanup_note}",
            destination.display()
        )));
    }

    if json {
        print_json(&serde_json::json!({
            "created": true,
            "path": destination,
            "contains_credentials": false,
            "next": ["kitsu", "--config", destination, "doctor"],
        }))
    } else {
        println!(
            "created no-secret starter config at {}",
            terminal_inline(&destination.to_string_lossy())
        );
        let next = format!(
            "kitsu --config {} doctor",
            shell_quote(&destination.to_string_lossy())
        );
        println!("next: {}", terminal_inline(&next));
        Ok(())
    }
}

fn trim_secret_line_ending(mut bytes: zeroize::Zeroizing<Vec<u8>>) -> zeroize::Zeroizing<Vec<u8>> {
    if bytes.last() == Some(&b'\n') {
        bytes.pop();
        if bytes.last() == Some(&b'\r') {
            bytes.pop();
        }
    }
    bytes
}

fn read_secret_stdin() -> Result<zeroize::Zeroizing<Vec<u8>>, CliError> {
    use std::io::Read as _;
    let limit = credential_store::MAX_CREDENTIAL_BYTES.saturating_add(2);
    let mut bytes = zeroize::Zeroizing::new(Vec::with_capacity(limit.min(4096)));
    std::io::stdin()
        .lock()
        .take(u64::try_from(limit).unwrap_or(u64::MAX))
        .read_to_end(&mut bytes)
        .map_err(|error| CliError::user(format!("cannot read managed credential: {error}")))?;
    if bytes.len() >= limit {
        return Err(CliError::user(
            "managed credential exceeds the 16 KiB safety limit",
        ));
    }
    Ok(trim_secret_line_ending(bytes))
}

#[cfg(unix)]
struct TerminalEchoGuard {
    fd: std::os::fd::RawFd,
    original: libc::termios,
}

#[cfg(unix)]
impl Drop for TerminalEchoGuard {
    fn drop(&mut self) {
        unsafe {
            libc::tcsetattr(self.fd, libc::TCSANOW, &self.original);
        }
    }
}

#[cfg(unix)]
async fn read_secret_tty() -> Result<zeroize::Zeroizing<Vec<u8>>, CliError> {
    use std::io::{Read as _, Write as _};
    use std::os::fd::{AsRawFd as _, FromRawFd as _};

    if unsafe { libc::isatty(libc::STDIN_FILENO) } != 1 {
        return Err(CliError::user(
            "auth login requires a terminal for hidden input; use --token-stdin for a secret-manager pipeline",
        ));
    }
    let fd = unsafe { libc::dup(libc::STDIN_FILENO) };
    if fd < 0 {
        return Err(CliError::user(
            "cannot duplicate terminal input; use --token-stdin instead",
        ));
    }
    let file = unsafe { std::fs::File::from_raw_fd(fd) };
    let flags = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_GETFL) };
    if flags < 0
        || unsafe { libc::fcntl(file.as_raw_fd(), libc::F_SETFL, flags | libc::O_NONBLOCK) } != 0
    {
        return Err(CliError::user(
            "cannot prepare terminal input; use --token-stdin instead",
        ));
    }
    let mut original = std::mem::MaybeUninit::<libc::termios>::uninit();
    if unsafe { libc::tcgetattr(file.as_raw_fd(), original.as_mut_ptr()) } != 0 {
        return Err(CliError::user(
            "cannot prepare hidden terminal input; use --token-stdin instead",
        ));
    }
    let original = unsafe { original.assume_init() };
    let mut hidden = original;
    hidden.c_lflag &= !libc::ECHO;
    if unsafe { libc::tcsetattr(file.as_raw_fd(), libc::TCSAFLUSH, &hidden) } != 0 {
        return Err(CliError::user(
            "cannot disable terminal echo; use --token-stdin instead",
        ));
    }
    let echo_guard = TerminalEchoGuard {
        fd: file.as_raw_fd(),
        original,
    };
    std::eprint!("credential: ");
    std::io::stderr()
        .flush()
        .map_err(|error| CliError::user(format!("cannot write credential prompt: {error}")))?;

    let async_file = tokio::io::unix::AsyncFd::new(file)
        .map_err(|error| CliError::user(format!("cannot monitor terminal input: {error}")))?;
    let read = async {
        let limit = credential_store::MAX_CREDENTIAL_BYTES.saturating_add(2);
        let mut bytes = zeroize::Zeroizing::new(Vec::with_capacity(limit.min(4096)));
        loop {
            let mut ready = async_file.readable().await.map_err(|error| {
                CliError::user(format!("cannot wait for managed credential input: {error}"))
            })?;
            let mut chunk = [0_u8; 1024];
            match ready.try_io(|inner| {
                let mut file = inner.get_ref();
                file.read(&mut chunk)
            }) {
                Ok(Ok(0)) => break,
                Ok(Ok(read)) => {
                    bytes.extend_from_slice(&chunk[..read]);
                    if bytes.contains(&b'\n') {
                        break;
                    }
                    if bytes.len() >= limit {
                        return Err(CliError::user(
                            "managed credential exceeds the 16 KiB safety limit",
                        ));
                    }
                }
                Ok(Err(error)) => {
                    return Err(CliError::user(format!(
                        "cannot read managed credential: {error}"
                    )))
                }
                Err(_) => continue,
            }
        }
        Ok(trim_secret_line_ending(bytes))
    };
    let result = tokio::select! {
        result = read => result,
        _ = tokio::signal::ctrl_c() => Err(CliError::cancelled("auth login cancelled; no credential was stored")),
    };
    drop(echo_guard);
    std::eprintln!();
    result
}

#[cfg(not(unix))]
async fn read_secret_tty() -> Result<zeroize::Zeroizing<Vec<u8>>, CliError> {
    Err(CliError::user(
        "hidden terminal credential input is unavailable on this platform; use --token-stdin",
    ))
}

fn environment_override_present(gateway: &Gateway) -> bool {
    gateway.auth.method == "bearer-env"
        && std::env::var_os(&gateway.auth.env).is_some_and(|value| !value.is_empty())
}

fn require_persistent_credential_home() -> Result<(), CliError> {
    let Some(home) = kitsu_tools::host_home_dir() else {
        return Err(CliError::user(
            "auth login requires an absolute home directory (HOME, or USERPROFILE on Windows) so credentials are never persisted in temporary fallback state",
        ));
    };
    if !std::path::Path::new(&home).is_absolute() {
        return Err(CliError::user(
            "auth login requires an absolute HOME so credentials are never persisted in temporary fallback state",
        ));
    }
    Ok(())
}

fn managed_credential(
    state_dir: &std::path::Path,
    gateway_name: &str,
    gateway: &Gateway,
) -> Result<Option<zeroize::Zeroizing<String>>, CliError> {
    if gateway.auth.method != "bearer-env" {
        return Ok(None);
    }
    credential_store::load(state_dir, gateway_name).map_err(CliError::user)
}

fn reject_credential_command_root(
    root: &std::path::Path,
    state_dir: &std::path::Path,
    flag: &str,
) -> Result<(), CliError> {
    let state = std::fs::canonicalize(state_dir).unwrap_or_else(|_| state_dir.to_path_buf());
    let credentials = credential_store::directory_path(&state);
    if credentials.starts_with(root) || root.starts_with(&credentials) {
        return Err(CliError::user(format!(
            "{flag} '{}' intersects Kitsu's managed-credential namespace; use a narrower project/toolchain root",
            terminal_inline(&root.display().to_string())
        )));
    }
    Ok(())
}

fn auth_status_payload(
    gateway_name: &str,
    gateway: &Gateway,
    managed: Option<zeroize::Zeroizing<String>>,
) -> (serde_json::Value, bool) {
    let environment_present = environment_override_present(gateway);
    let managed_present = managed.is_some();
    let effective_source = match gateway.auth.method.as_str() {
        "none" => "none",
        "static" => "static",
        "bearer-env" if environment_present => "environment",
        "bearer-env" if managed_present => "managed",
        "bearer-env" => "missing",
        _ => "unsupported",
    };
    let credential_present = match gateway.auth.method.as_str() {
        "none" => false,
        "static" => gateway
            .auth
            .token
            .as_deref()
            .is_some_and(|token| !token.is_empty()),
        "bearer-env" => environment_present || managed_present,
        _ => false,
    };
    let locally_usable =
        build_auth(gateway, gateway_name, managed).is_ok_and(|auth| auth.header().is_ok());
    (
        serde_json::json!({
            "gateway": gateway_name,
            "method": gateway.auth.method,
            "credential_present": credential_present,
            "effective_source": effective_source,
            "environment_override_present": environment_present,
            "managed_credential_present": managed_present,
            "locally_usable": locally_usable,
            "remote_validity_checked": false,
            "request_sent": false,
        }),
        locally_usable,
    )
}

async fn run_auth(cli: &Cli, json: bool, command: &AuthCommand) -> Result<(), CliError> {
    reject_jsonl_for_management(cli, "kitsu auth status --json")?;
    let config_path = Config::resolve_path(cli.config.as_deref());
    if !config_path.is_file() {
        return Err(CliError::user(format!(
            "config error: no readable config found at {}",
            shorten_home(&config_path)
        )));
    }
    let config =
        Config::load(&config_path).map_err(|error| CliError::user(safe_config_error(&error)))?;
    let (gateway_name, gateway) = config
        .select_gateway(cli.gateway.as_deref())
        .map_err(|error| CliError::user(error.to_string()))?;
    gateway
        .validate_auth()
        .map_err(|error| CliError::user(error.to_string()))?;
    let gateway_name = gateway_name.to_string();

    match command {
        AuthCommand::Login { token_stdin } => {
            if gateway.auth.method != "bearer-env" {
                return Err(CliError::user(format!(
                    "auth login supports bearer-env gateways; '{}' uses {}",
                    terminal_inline(&gateway_name),
                    terminal_inline(&gateway.auth.method)
                )));
            }
            require_persistent_credential_home()?;
            let bytes = if *token_stdin {
                read_secret_stdin()?
            } else {
                read_secret_tty().await?
            };
            let token = credential_store::decode_zeroizing(bytes).map_err(CliError::user)?;
            let validator = EnvBearerAuth {
                env: gateway.auth.env.clone(),
                expires_env: gateway.auth.expires_env.clone(),
                header: gateway.auth.header.clone(),
                scheme: gateway.auth.scheme.clone(),
                refresh_hint: None,
                managed_token: None,
            };
            validator
                .validate_managed_token(token.as_str())
                .map_err(|_| CliError::user("managed credential is not a valid HTTP credential"))?;
            let state_dir = runtime_state_dir(&config_path);
            credential_store::store(&state_dir, &gateway_name, token.as_str())
                .map_err(CliError::user)?;
            let managed = managed_credential(&state_dir, &gateway_name, gateway)?;
            let (mut report, _) = auth_status_payload(&gateway_name, gateway, managed);
            report["stored"] = serde_json::Value::Bool(true);
            if json {
                print_json(&report)?;
            } else {
                println!(
                    "managed credential stored for gateway {}; effective source: {}",
                    terminal_inline(&gateway_name),
                    report["effective_source"].as_str().unwrap_or("unknown")
                );
                println!(
                    "remote validity was not checked; run `kitsu --gateway {} doctor --inference`",
                    terminal_inline(&gateway_name)
                );
            }
            Ok(())
        }
        AuthCommand::Status => {
            let state_dir = runtime_state_dir_read_only(&config_path);
            let managed = managed_credential(&state_dir, &gateway_name, gateway)?;
            let (report, locally_usable) = auth_status_payload(&gateway_name, gateway, managed);
            if json {
                print_json(&report)?;
            } else {
                println!(
                    "gateway {}: {} (source: {}; remote validity not checked)",
                    terminal_inline(&gateway_name),
                    if locally_usable {
                        "credential locally usable"
                    } else {
                        "credential unavailable or malformed"
                    },
                    report["effective_source"].as_str().unwrap_or("unknown")
                );
            }
            if locally_usable {
                Ok(())
            } else {
                Err(CliError::user(
                    "authentication is not locally usable; run `kitsu auth login` or set the configured environment variable",
                ))
            }
        }
        AuthCommand::Logout => {
            if gateway.auth.method != "bearer-env" {
                return Err(CliError::user(format!(
                    "auth logout supports bearer-env gateways; '{}' uses {}",
                    terminal_inline(&gateway_name),
                    terminal_inline(&gateway.auth.method)
                )));
            }
            let state_dir = runtime_state_dir_read_only(&config_path);
            let removed =
                credential_store::remove(&state_dir, &gateway_name).map_err(CliError::user)?;
            let managed = managed_credential(&state_dir, &gateway_name, gateway)?;
            let (mut report, _) = auth_status_payload(&gateway_name, gateway, managed);
            report["removed"] = serde_json::Value::Bool(removed);
            if json {
                print_json(&report)?;
            } else {
                println!(
                    "{} managed credential for gateway {}; effective source: {}",
                    if removed { "removed" } else { "no" },
                    terminal_inline(&gateway_name),
                    report["effective_source"].as_str().unwrap_or("unknown")
                );
                if report["environment_override_present"] == true {
                    println!("the configured environment credential remains effective");
                }
            }
            Ok(())
        }
    }
}

fn shell_quote(value: &str) -> String {
    #[cfg(unix)]
    {
        if !value.is_empty()
            && value.bytes().all(|byte| {
                byte.is_ascii_alphanumeric() || matches!(byte, b'/' | b'.' | b'_' | b'-' | b':')
            })
        {
            value.to_string()
        } else {
            format!("'{}'", value.replace('\'', "'\\''"))
        }
    }
    #[cfg(not(unix))]
    {
        serde_json::to_string(value).unwrap_or_else(|_| "\"<path>\"".to_string())
    }
}

fn resume_argv(config_path: &std::path::Path, id: &str) -> Vec<String> {
    vec![
        "kitsu".to_string(),
        "--config".to_string(),
        config_path.to_string_lossy().into_owned(),
        "chat".to_string(),
        "--resume".to_string(),
        id.to_string(),
    ]
}

fn display_argv(argv: &[String]) -> String {
    argv.iter()
        .map(|argument| shell_quote(argument))
        .collect::<Vec<_>>()
        .join(" ")
}

fn runnable_resume_command(directory: &str, argv: &[String]) -> String {
    #[cfg(unix)]
    {
        format!("cd {} && {}", shell_quote(directory), display_argv(argv))
    }
    #[cfg(not(unix))]
    {
        // JSON output carries `cwd` separately for portable process launchers.
        // Keep the human fallback explicit instead of guessing a shell dialect.
        format!("(from {}) {}", shell_quote(directory), display_argv(argv))
    }
}

fn session_error(
    operation: &str,
    config_path: &std::path::Path,
    error: impl std::fmt::Display,
) -> CliError {
    CliError::user(format!(
        "cannot {operation} session in the namespace for config '{}': {error}",
        config_path.display()
    ))
}

fn require_session_namespace(
    sessions_dir: &std::path::Path,
    operation: &str,
    config_path: &std::path::Path,
) -> Result<(), CliError> {
    match std::fs::symlink_metadata(sessions_dir) {
        Ok(_) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Err(session_error(
            operation,
            config_path,
            "no saved sessions in this config directory",
        )),
        // Let SessionStore produce its descriptor/file-type-specific error for
        // permission failures, symlinks, and irregular existing entries.
        Err(_) => Ok(()),
    }
}

fn role_label(role: kitsu_providers::Role) -> &'static str {
    match role {
        kitsu_providers::Role::System => "system",
        kitsu_providers::Role::User => "user",
        kitsu_providers::Role::Assistant => "assistant",
        kitsu_providers::Role::Tool => "tool",
    }
}

fn format_saved_session(saved: &session::SavedSession) -> String {
    const MAX_TRANSCRIPT_BYTES: usize = 64 * 1024;
    let mut output = format!(
        "session {}\nupdated: {}\ngateway/model: {}/{}\ndirectory: {}\nmessages: {}\n\n",
        terminal_inline(&saved.id),
        terminal_inline(&saved.updated_at),
        terminal_inline(&saved.gateway),
        terminal_inline(&saved.model),
        shorten_home(std::path::Path::new(&saved.directory)),
        saved.messages.len(),
    );
    let mut truncated = false;
    for message in &saved.messages {
        let content = kitsu_render::sanitize_terminal_text(&message.content);
        let block = format!("[{}]\n{}\n\n", role_label(message.role), content);
        let remaining = MAX_TRANSCRIPT_BYTES.saturating_sub(output.len());
        if block.len() <= remaining {
            output.push_str(&block);
            continue;
        }
        let mut boundary = remaining.min(block.len());
        while boundary > 0 && !block.is_char_boundary(boundary) {
            boundary -= 1;
        }
        output.push_str(&block[..boundary]);
        truncated = true;
        break;
    }
    if truncated {
        output.push_str(
            "\n\n[transcript truncated at 64 KiB; use --json or export for the complete snapshot]\n",
        );
    }
    output
}

fn artifact_generation_payload(generation: &artifacts::Generation) -> serde_json::Value {
    serde_json::json!({
        "id": generation.id,
        "path": generation.path,
        "namespace": generation.namespace.label(),
        "files": generation.files,
        "bytes": generation.bytes,
        "age_secs": generation.age_secs,
        "state": generation.retention.label(),
        "prunable": generation.prunable(),
    })
}

fn format_artifact_inventory(
    generations: &[artifacts::Generation],
    config_path: &std::path::Path,
) -> String {
    let mut out = format!("command artifacts for config {}", shorten_home(config_path));
    for namespace in [
        artifacts::Namespace::Runtime,
        artifacts::Namespace::Sessions,
    ] {
        let group = generations
            .iter()
            .filter(|generation| generation.namespace == namespace)
            .collect::<Vec<_>>();
        if group.is_empty() {
            continue;
        }
        out.push_str(&format!("\n  namespace {}", namespace.label()));
        for generation in group {
            out.push_str(&format!(
                "\n    {:<40} {:>3} file(s) {:>10}  {:<9} {}",
                terminal_inline(&generation.id),
                generation.files,
                artifacts::human_bytes(generation.bytes),
                artifacts::human_age(generation.age_secs),
                generation.retention.label(),
            ));
        }
    }
    let total_bytes: u64 = generations.iter().map(|generation| generation.bytes).sum();
    let prunable = generations
        .iter()
        .filter(|generation| generation.prunable())
        .count();
    let live = generations
        .iter()
        .filter(|generation| generation.retention == artifacts::Retention::InUse)
        .count();
    out.push_str(&format!(
        "\n  total {} generation(s), {}; {prunable} prunable, {live} in use by a live process",
        generations.len(),
        artifacts::human_bytes(total_bytes),
    ));
    out.push_str(
        "\n  prune with: kitsu artifacts prune all | kitsu artifacts prune all --older-than 7d",
    );
    out
}

/// `kitsu artifacts` — provider-free, offline, host-only inventory and pruning
/// of storage left by earlier runs. Listing is strictly read-only: merely
/// looking at disk state must not materialize a profile directory.
fn run_artifacts(
    cli: &Cli,
    json: bool,
    command: Option<&cli::ArtifactCommand>,
) -> Result<(), CliError> {
    reject_jsonl_for_management(cli, "kitsu artifacts --json")?;
    let config_path = Config::resolve_path(cli.config.as_deref());
    let state_dir = runtime_state_dir_read_only(&config_path);
    let generations = artifacts::scan(&state_dir).map_err(CliError::user)?;

    match command {
        None | Some(cli::ArtifactCommand::List) => {
            if json {
                return print_json(&serde_json::json!({
                    "action": "list",
                    "state_dir": state_dir,
                    "generations": generations
                        .iter()
                        .map(artifact_generation_payload)
                        .collect::<Vec<_>>(),
                    "total_bytes": generations.iter().map(|generation| generation.bytes).sum::<u64>(),
                }));
            }
            if generations.is_empty() {
                println!(
                    "no retained command artifacts for config {}",
                    shorten_home(&config_path)
                );
                return Ok(());
            }
            println!("{}", format_artifact_inventory(&generations, &config_path));
            Ok(())
        }
        Some(cli::ArtifactCommand::Prune {
            target,
            older_than,
            dry_run,
        }) => {
            let minimum_age = older_than
                .as_deref()
                .map(artifacts::parse_duration_secs)
                .transpose()
                .map_err(CliError::user)?;
            let selected = generations
                .iter()
                .filter(|generation| target == "all" || &generation.id == target)
                .collect::<Vec<_>>();
            if selected.is_empty() {
                return Err(CliError::user(format!(
                    "no retained artifact generation matches {}; run 'kitsu artifacts list' to see what exists",
                    terminal_inline(target)
                )));
            }
            let mut removed = Vec::new();
            let mut skipped = Vec::new();
            let mut reclaimed = 0u64;
            for generation in selected {
                if !generation.prunable() {
                    skipped.push((generation, skip_reason(generation)));
                    continue;
                }
                if minimum_age.is_some_and(|minimum| {
                    generation.age_secs.map(|age| age < minimum).unwrap_or(true)
                }) {
                    skipped.push((generation, "newer than --older-than".to_string()));
                    continue;
                }
                if *dry_run {
                    reclaimed += generation.bytes;
                    removed.push(generation);
                    continue;
                }
                match artifacts::remove(generation) {
                    Ok(()) => {
                        reclaimed += generation.bytes;
                        removed.push(generation);
                    }
                    Err(error) => skipped.push((generation, error)),
                }
            }
            if json {
                return print_json(&serde_json::json!({
                    "action": if *dry_run { "prune_dry_run" } else { "prune" },
                    "removed": removed
                        .iter()
                        .map(|generation| artifact_generation_payload(generation))
                        .collect::<Vec<_>>(),
                    "skipped": skipped
                        .iter()
                        .map(|(generation, reason)| serde_json::json!({
                            "id": generation.id,
                            "reason": reason,
                        }))
                        .collect::<Vec<_>>(),
                    "reclaimed_bytes": reclaimed,
                }));
            }
            println!(
                "{} {} generation(s), {}",
                if *dry_run { "would remove" } else { "removed" },
                removed.len(),
                artifacts::human_bytes(reclaimed)
            );
            for (generation, reason) in &skipped {
                println!("  skipped {}: {reason}", terminal_inline(&generation.id));
            }
            if removed.is_empty() {
                return Err(CliError::user(
                    "nothing was removed; every matching generation is still in use or owned"
                        .to_string(),
                ));
            }
            Ok(())
        }
    }
}

fn skip_reason(generation: &artifacts::Generation) -> String {
    match generation.retention {
        artifacts::Retention::InUse => "a live process holds this generation's lock".to_string(),
        artifacts::Retention::SessionExists => {
            "its session still exists; use 'kitsu sessions delete <id>' first".to_string()
        }
        artifacts::Retention::Orphaned => format!(
            "no lock file and younger than the {}s liveness grace period",
            artifacts::UNLOCKED_GRACE_SECS
        ),
    }
}

/// `kitsu agents`: the background agents every kitsu on this machine is
/// publishing. Host-only and read-only — it opens no provider, makes no
/// inference request, needs no config, and reclaims no state file.
fn run_agents(cli: &Cli, json: bool, all: bool) -> Result<(), CliError> {
    reject_jsonl_for_management(cli, "kitsu agents --json")?;
    let entries = agent_state_file::list_entries(
        &agent_state_file::state_dir(),
        all,
        &agent_state_file::process_is_alive,
    );
    if json {
        // A listing like `kitsu sessions --json`: the bare array, with no
        // action envelope.
        print_json(&entries)
    } else {
        println!("{}", agent_state_file::format_agents_listing(&entries));
        Ok(())
    }
}

async fn run_sessions(
    cli: &Cli,
    json: bool,
    command: Option<&SessionCommand>,
) -> Result<(), CliError> {
    reject_jsonl_for_management(cli, "kitsu sessions --json")?;
    let config_path = Config::resolve_path(cli.config.as_deref());
    let state_dir = runtime_state_dir_read_only(&config_path);
    let sessions_dir = state_dir.join("sessions");

    match command {
        None => {
            let saved = session::SessionStore::list(&sessions_dir)
                .map_err(|error| session_error("list", &config_path, error))?;
            if json {
                print_json(&saved)
            } else if saved.is_empty() {
                println!(
                    "no saved sessions for config {} — start one with kitsu chat --session (add --name <name> for a memorable handle) or /new",
                    shorten_home(&config_path)
                );
                Ok(())
            } else {
                println!("{}", format_session_summaries(&saved, None, ""));
                Ok(())
            }
        }
        Some(SessionCommand::List { filter }) => {
            let saved = session::SessionStore::list(&sessions_dir)
                .map_err(|error| session_error("list", &config_path, error))?;
            let filter_str = filter.as_deref().unwrap_or("");
            if json {
                let filtered = filter_sessions(&saved, filter_str);
                print_json(&filtered)
            } else if saved.is_empty() {
                println!(
                    "no saved sessions for config {} — start one with kitsu chat --session (add --name <name> for a memorable handle) or /new",
                    shorten_home(&config_path)
                );
                Ok(())
            } else {
                println!("{}", format_session_summaries(&saved, None, filter_str));
                Ok(())
            }
        }
        Some(SessionCommand::Show { id }) => {
            require_session_namespace(&sessions_dir, "show", &config_path)?;
            let saved = session::SessionStore::load(&sessions_dir, id)
                .map_err(|error| session_error("show", &config_path, error))?;
            if json {
                print_json(&saved)
            } else {
                print!("{}", format_saved_session(&saved));
                Ok(())
            }
        }
        Some(SessionCommand::Resume { id }) => {
            require_session_namespace(&sessions_dir, "resume", &config_path)?;
            let saved = session::SessionStore::load(&sessions_dir, id)
                .map_err(|error| session_error("resume", &config_path, error))?;
            if json || !kitsu_render::stdin_is_tty() {
                let argv = resume_argv(&config_path, &saved.id);
                if json {
                    print_json(&serde_json::json!({
                        "action": "resume",
                        "launched": false,
                        "session_id": saved.id,
                        "cwd": saved.directory,
                        "argv": argv,
                    }))
                } else {
                    println!(
                        "resume with: {}",
                        terminal_inline(&runnable_resume_command(&saved.directory, &argv))
                    );
                    println!("working directory: {}", terminal_inline(&saved.directory));
                    println!(
                        "exact argv: {}",
                        serde_json::to_string(&argv)
                            .unwrap_or_else(|_| "[\"kitsu\", \"chat\"]".to_string())
                    );
                    Ok(())
                }
            } else {
                run_chat(
                    cli,
                    ChatInvocation {
                        first_prompt: None,
                        no_tools: false,
                        allow_paths: &[],
                        allow_write: &[],
                        allow_read_write: &[],
                        require_writes: &[],
                        require_write_sha256: &[],
                        enable_commands: false,
                        command_roots: &[],
                        command_runtime_roots: &[],
                        command_env: &[],
                        allow_commands: &[],
                        script: None,
                        resume: Some(&saved.id),
                        persist_session: false,
                        no_session: false,
                        session_name: None,
                        allow_turn_errors: false,
                        initial_review: None,
                    },
                )
                .await
            }
        }
        Some(SessionCommand::Fork { id }) => {
            require_session_namespace(&sessions_dir, "fork", &config_path)?;
            let forked = session::SessionStore::fork_with_source(&sessions_dir, id)
                .map_err(|error| session_error("fork", &config_path, error))?;
            if json {
                print_json(&serde_json::json!({
                    "action": "fork",
                    "source_session_id": forked.source_session_id,
                    "session": forked.session,
                    "permissions_restored": false,
                }))
            } else {
                println!(
                    "forked session {} -> {} (permissions were not copied)",
                    terminal_inline(&forked.source_session_id),
                    terminal_inline(&forked.session.id)
                );
                Ok(())
            }
        }
        Some(SessionCommand::Export {
            id,
            destination,
            format,
        }) => {
            require_session_namespace(&sessions_dir, "export", &config_path)?;
            let format = match format.as_deref() {
                Some("markdown") => session::SessionExportFormat::Markdown,
                Some("json") => session::SessionExportFormat::Json,
                Some(_) => unreachable!("clap validates session export format"),
                // An explicit --format always wins; inference only fills the gap
                // that used to silently write Markdown into a .json file.
                None => {
                    let inferred = inferred_export_format(destination);
                    if inferred == session::SessionExportFormat::Json && !json {
                        eprintln!("~ inferred --format json from the .json destination");
                    }
                    inferred
                }
            };
            let output = session::SessionStore::export(&sessions_dir, id, destination, format)
                .map_err(|error| session_error("export", &config_path, error))?;
            if json {
                print_json(&serde_json::json!({"action": "export", "path": output}))
            } else {
                println!("exported session to {}", output.display());
                Ok(())
            }
        }
        Some(SessionCommand::Rename { id, name }) => {
            require_session_namespace(&sessions_dir, "rename", &config_path)?;
            let saved = session::SessionStore::rename(&sessions_dir, id, name.as_deref())
                .map_err(|error| session_error("rename", &config_path, error))?;
            if json {
                print_json(&serde_json::json!({
                    "action": "rename",
                    "id": saved.id,
                    "name": saved.name,
                }))
            } else {
                match &saved.name {
                    Some(new_name) => println!(
                        "named session {} '{}' — resume it with `kitsu chat --resume {}`",
                        terminal_inline(&saved.id),
                        terminal_inline(new_name),
                        terminal_inline(new_name),
                    ),
                    None => println!("cleared the name of session {}", terminal_inline(&saved.id)),
                }
                Ok(())
            }
        }
        Some(SessionCommand::Archive { id }) => {
            require_session_namespace(&sessions_dir, "archive", &config_path)?;
            session::SessionStore::load(&sessions_dir, id)
                .map_err(|error| session_error("archive", &config_path, error))?;
            let output = session::SessionStore::archive(&sessions_dir, id, None)
                .map_err(|error| session_error("archive", &config_path, error))?;
            if json {
                print_json(&serde_json::json!({"action": "archive", "id": id, "path": output}))
            } else {
                println!("archived session {}", terminal_inline(id));
                Ok(())
            }
        }
        Some(SessionCommand::Restore { id }) => {
            require_session_namespace(&sessions_dir, "restore", &config_path)?;
            let saved = session::SessionStore::restore_archived(&sessions_dir, id)
                .map_err(|error| session_error("restore", &config_path, error))?;
            if json {
                print_json(&serde_json::json!({"action": "restore", "session": saved}))
            } else {
                println!("restored session {}", terminal_inline(&saved.id));
                Ok(())
            }
        }
        Some(SessionCommand::Delete { id }) => {
            require_session_namespace(&sessions_dir, "delete", &config_path)?;
            session::SessionStore::load(&sessions_dir, id)
                .map_err(|error| session_error("delete", &config_path, error))?;
            session::SessionStore::delete(&sessions_dir, id, None)
                .map_err(|error| session_error("delete", &config_path, error))?;
            if json {
                print_json(&serde_json::json!({"action": "delete", "id": id, "deleted": true}))
            } else {
                println!("deleted session {}", terminal_inline(id));
                Ok(())
            }
        }
    }
}

fn config_resolution_source(cli: &Cli) -> &'static str {
    if cli.config.is_some() {
        "--config"
    } else if std::env::var_os("KITSU_CONFIG").is_some_and(|value| !value.is_empty()) {
        "KITSU_CONFIG"
    } else {
        "default"
    }
}

#[cfg(unix)]
fn directory_is_writable(path: &std::path::Path) -> bool {
    use std::os::unix::ffi::OsStrExt as _;
    let Ok(path) = std::ffi::CString::new(path.as_os_str().as_bytes()) else {
        return false;
    };
    unsafe { libc::access(path.as_ptr(), libc::W_OK | libc::X_OK) == 0 }
}

#[cfg(not(unix))]
fn directory_is_writable(path: &std::path::Path) -> bool {
    std::fs::metadata(path)
        .map(|metadata| metadata.is_dir() && !metadata.permissions().readonly())
        .unwrap_or(false)
}

fn runtime_state_diagnostic(path: &std::path::Path) -> serde_json::Value {
    match std::fs::symlink_metadata(path) {
        Ok(metadata) if metadata.file_type().is_symlink() => serde_json::json!({
            "path": path,
            "exists": true,
            "writable": false,
            "status": "unsafe: state path is a symlink",
        }),
        Ok(metadata) if !metadata.file_type().is_dir() => serde_json::json!({
            "path": path,
            "exists": true,
            "writable": false,
            "status": "unusable: state path is not a directory",
        }),
        Ok(_) => {
            let writable = directory_is_writable(path);
            serde_json::json!({
                "path": path,
                "exists": true,
                "writable": writable,
                "status": if writable { "writable" } else { "not writable" },
            })
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            let mut ancestor = path.parent();
            let mut nearest = None;
            while let Some(candidate) = ancestor {
                match std::fs::canonicalize(candidate) {
                    Ok(existing) if existing.is_dir() => {
                        nearest = Some(existing);
                        break;
                    }
                    _ => ancestor = candidate.parent(),
                }
            }
            let writable = nearest
                .as_deref()
                .map(directory_is_writable)
                .unwrap_or(false);
            serde_json::json!({
                "path": path,
                "exists": false,
                "writable": writable,
                "nearest_existing_ancestor": nearest,
                "status": if writable {
                    "not created; nearest parent is writable"
                } else {
                    "not created; nearest parent is not writable"
                },
            })
        }
        Err(error) => serde_json::json!({
            "path": path,
            "exists": false,
            "writable": false,
            "status": format!("cannot inspect state path: {}", error.kind()),
        }),
    }
}

fn safe_config_error(error: &ConfigError) -> String {
    match error {
        ConfigError::Parse { .. } => error.to_string(),
        ConfigError::Read { source, .. } => {
            format!("cannot read config: {}", source.kind())
        }
        other => other.to_string(),
    }
}

#[derive(Clone, Copy)]
enum ProviderOperation<'a> {
    Chat { model: &'a str },
    InferenceProbe { model: &'a str },
    ModelCatalog,
}

/// Secret-free provider metadata used only to choose bounded recovery prose.
/// The raw base URL never enters an error message: config may contain userinfo
/// or query credentials, so reduce it to the one trusted fact the formatter
/// needs while setup still owns the parsed gateway profile.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct ProviderDiagnosticContext {
    loopback_ollama: bool,
}

/// Stable, secret-free machine diagnostics for provider failures whose cause
/// Kitsu can determine from trusted configuration. These codes supplement the
/// human message; they never contain provider text or endpoint components.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ProviderDiagnosticCode {
    LocalOllamaUnreachable,
}

impl ProviderDiagnosticCode {
    const fn code(self) -> &'static str {
        match self {
            Self::LocalOllamaUnreachable => "local_ollama_unreachable",
        }
    }

    const fn recovery_actions(self) -> &'static [&'static str] {
        match self {
            Self::LocalOllamaUnreachable => &[
                "start_ollama_serve",
                "verify_ollama_serve",
                "select_another_gateway",
            ],
        }
    }
}

impl ProviderDiagnosticContext {
    fn from_gateway(gateway_name: &str, gateway: &Gateway) -> Self {
        let ollama_profile = gateway_name.eq_ignore_ascii_case("ollama")
            || gateway.flavor.eq_ignore_ascii_case("ollama");
        Self {
            loopback_ollama: ollama_profile && base_url_has_loopback_host(&gateway.base_url),
        }
    }

    fn code_for(self, error: &ProviderError) -> Option<ProviderDiagnosticCode> {
        if self.loopback_ollama && matches!(error, ProviderError::Connection(_)) {
            Some(ProviderDiagnosticCode::LocalOllamaUnreachable)
        } else {
            None
        }
    }
}

/// Recognize only URL-shaped loopback endpoints. This deliberately does not
/// resolve names or accept prefix matches such as `localhost.example.com`.
fn base_url_has_loopback_host(base_url: &str) -> bool {
    let Some((scheme, remainder)) = base_url.split_once("://") else {
        return false;
    };
    if !matches!(scheme.to_ascii_lowercase().as_str(), "http" | "https") {
        return false;
    }
    let authority = remainder
        .split(['/', '?', '#'])
        .next()
        .unwrap_or_default()
        .rsplit('@')
        .next()
        .unwrap_or_default();
    let host = if let Some(bracketed) = authority.strip_prefix('[') {
        let Some(end) = bracketed.find(']') else {
            return false;
        };
        &bracketed[..end]
    } else {
        authority
            .rsplit_once(':')
            .filter(|(_, port)| !port.is_empty() && port.bytes().all(|byte| byte.is_ascii_digit()))
            .map_or(authority, |(host, _)| host)
    };
    host.eq_ignore_ascii_case("localhost")
        || host
            .parse::<std::net::IpAddr>()
            .is_ok_and(|address| address.is_loopback())
}

impl ProviderOperation<'_> {
    fn subject(self) -> &'static str {
        match self {
            Self::Chat { .. } => "chat request",
            Self::InferenceProbe { .. } => "inference probe",
            Self::ModelCatalog => "model catalog request",
        }
    }
}

fn safe_auth_refresh_hint(hint: Option<&str>) -> Option<String> {
    let hint = terminal_inline(hint?).trim().to_string();
    if hint.is_empty() {
        return None;
    }
    let bounded: String = hint.chars().take(240).collect();
    if refresh_hint_contains_credential(&bounded) {
        return None;
    }
    Some(bounded)
}

/// Refresh hints are configuration-controlled prose, but are routinely copied
/// from credential setup snippets. Reject the entire hint if it resembles a
/// URL, header, assignment, or common hosted-provider token. Keeping a partial
/// redaction would still disclose useful credential fragments.
fn refresh_hint_contains_credential(hint: &str) -> bool {
    let lowered = hint.to_ascii_lowercase();
    if [
        "://",
        "api_key",
        "api-key",
        "api key",
        "apikey",
        "authorization",
        "bearer ",
        "password",
        "secret",
        "access_token",
        "access-token",
        "access token",
    ]
    .iter()
    .any(|marker| lowered.contains(marker))
        || hint.contains("hf_")
        || hint.contains("sk-")
    {
        return true;
    }

    // Reject a standalone `token` label followed by a value separator. A
    // hyphenated command such as `refresh-token` remains safe and actionable,
    // as do environment-variable names such as `HF_TOKEN`.
    for (start, _) in lowered.match_indices("token") {
        let before = lowered[..start].chars().next_back();
        if before.is_some_and(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-')) {
            continue;
        }
        let after = &lowered[start + "token".len()..];
        let mut chars = after.chars();
        match chars.next() {
            Some('=' | ':' | '"' | '\'' | '_' | '-') => return true,
            Some(ch) if ch.is_ascii_whitespace() => {
                if chars.any(|ch| !ch.is_ascii_whitespace()) {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

fn auth_refresh_hint_suffix(hint: Option<&str>) -> String {
    safe_auth_refresh_hint(hint)
        .map(|hint| format!("; configured refresh hint: {hint}"))
        .unwrap_or_default()
}

fn expired_auth_warning(since: &str, hint: Option<&str>) -> String {
    format!(
        "warning: gateway token expired (since {}) - sending anyway{}",
        terminal_inline(since),
        auth_refresh_hint_suffix(hint)
    )
}

/// One bounded formatter for every provider-facing surface. Provider-supplied
/// URL/body/detail strings are never interpolated; configured refresh hints are
/// accepted only when bounded and free of URL/credential-like markers.
fn safe_provider_error_message(
    error: &ProviderError,
    operation: ProviderOperation<'_>,
    timeout_secs: Option<u64>,
    diagnostics: ProviderDiagnosticContext,
) -> String {
    let subject = operation.subject();
    match error {
        ProviderError::Connection(_) if diagnostics.loopback_ollama => format!(
            "{subject} could not reach local Ollama at the configured loopback endpoint from this execution environment - start or verify `ollama serve`, or select another gateway"
        ),
        ProviderError::Connection(_) => format!(
            "{subject} could not reach the gateway - check the selected gateway's base_url, network access, and provider availability; run `kitsu doctor --online`"
        ),
        ProviderError::Timeout => match timeout_secs {
            Some(timeout_secs) => format!(
                "{subject} timed out after {timeout_secs}s - raise the budget with --timeout-secs <n> (e.g. --timeout-secs {}) for a slow, queued, or tool-heavy request",
                timeout_secs.saturating_mul(3).max(180)
            ),
            None => format!(
                "{subject} timed out - retry with a larger --timeout-secs budget if the gateway is slow or queued"
            ),
        },
        ProviderError::InvalidResponse(_) => format!(
            "{subject} received an invalid provider response - verify the gateway flavor and API compatibility"
        ),
        ProviderError::ResponseTooLarge { .. } => format!(
            "{subject} exceeded the provider response-size safety limit - reduce the requested output or catalog size and retry"
        ),
        ProviderError::Unauthorized { status: 403, hint } => {
            format!(
                "{subject} was forbidden (HTTP 403) - confirm the credential has inference and gated-model access{}",
                auth_refresh_hint_suffix(hint.as_deref())
            )
        }
        ProviderError::Unauthorized { status, hint } => {
            format!(
                "{subject} authentication/access was rejected (HTTP {status}) - refresh the configured credential and confirm model access{}",
                auth_refresh_hint_suffix(hint.as_deref())
            )
        }
        ProviderError::Http { status: 402, .. } => format!(
            "{subject} was rejected for billing or quota (HTTP 402) - check provider credits and billing settings"
        ),
        ProviderError::Http { status: 403, .. } => format!(
            "{subject} was forbidden (HTTP 403) - confirm the credential has inference and gated-model access"
        ),
        ProviderError::Http { status: 404, .. } => match operation {
            ProviderOperation::Chat { model } | ProviderOperation::InferenceProbe { model } => format!(
                "gateway rejected the chat route or model '{}' (HTTP 404) - verify the catalog with `kitsu models` or /models, run /model <valid-id>, and check the configured chat_path",
                terminal_inline(model)
            ),
            ProviderOperation::ModelCatalog => {
                "model catalog endpoint was not found (HTTP 404) - check models_path or disable catalog discovery".to_string()
            }
        },
        ProviderError::Http { status: 429, .. } => format!(
            "{subject} remained rate-limited after retries (HTTP 429) - wait for quota to recover or increase --timeout-secs so Retry-After can fit"
        ),
        ProviderError::Http { status, .. } if *status >= 500 => format!(
            "{subject} failed because the gateway is unavailable (HTTP {status}) - retry later or check provider status"
        ),
        ProviderError::Http { status, .. } if *status == 400 || *status == 422 => format!(
            "{subject} was rejected (HTTP {status}) - verify the selected model, gateway flavor, and request compatibility"
        ),
        ProviderError::Http { status, .. } => format!(
            "{subject} was rejected (HTTP {status}) - check gateway configuration and model access"
        ),
        ProviderError::ToolsNotSupported => format!(
            "{subject} requires tool calls that this provider does not support - disable tools or choose a tool-capable model"
        ),
        ProviderError::RouteContract(ProviderRouteContractError::StaleGeneration { .. }) => {
            format!(
                "{subject} was not sent because its provider route generation is stale - retry against the current route"
            )
        }
        ProviderError::RouteContract(ProviderRouteContractError::UnsupportedCapability {
            capability,
        }) => format!(
            "{subject} was not sent because the current provider route does not support {capability:?} - choose a compatible route or disable that request feature"
        ),
        ProviderError::RouteContract(ProviderRouteContractError::RequestModelMismatch) => format!(
            "{subject} was not sent because its model does not match the immutable provider route binding - retry against the current model route"
        ),
        ProviderError::RouteContract(_) => format!(
            "{subject} was not sent because the current provider route failed local admission - retry or rebuild the route from valid configuration"
        ),
        ProviderError::Auth(kitsu_providers::AuthError::Missing { env, hint }) => {
            format!(
                "credential variable ${} is missing - set it or update the gateway auth configuration{}",
                terminal_inline(env),
                auth_refresh_hint_suffix(hint.as_deref())
            )
        }
        ProviderError::Auth(kitsu_providers::AuthError::MissingStatic) => {
            "static credential is missing - configure it or select a different auth method"
                .to_string()
        }
        ProviderError::Auth(kitsu_providers::AuthError::Malformed { env }) => {
            format!(
                "credential variable ${} is malformed - replace it with a valid token",
                terminal_inline(env)
            )
        }
        ProviderError::Auth(kitsu_providers::AuthError::MalformedManaged) => {
            "managed credential is malformed - replace it with `kitsu auth login`"
                .to_string()
        }
    }
}

/// Integration hook for human-mode runtime notices. The event log can call
/// this beside its JSONL serializer; results contain only host-owned bounded
/// facts, numeric status/timing fields, and no provider-controlled text.
///
/// The success path stays silent: a first-attempt success is the normal case
/// and narrating it is transport noise. Retries, failures, and a success that
/// needed more than one attempt still report (JSONL mode keeps every event).
fn format_runtime_notice(event: &kitsu_core::AgentRuntimeEvent) -> Option<String> {
    if let kitsu_core::AgentRuntimeEvent::StructuredFinalizationDeferred {
        repair_round,
        targets,
        ..
    } = event
    {
        return Some(format!(
            "exact output mismatch; keeping tools available in repair round {repair_round} for {} target{}",
            targets.len(),
            if targets.len() == 1 { "" } else { "s" }
        ));
    }
    let kitsu_core::AgentRuntimeEvent::ProviderAttempt {
        purpose,
        attempt,
        max_attempts,
        category,
        status,
        outcome,
        terminal,
        retry_delay_ms,
        retry_after_used,
        remaining_deadline_ms,
        turn_remaining_ms,
        ..
    } = event
    else {
        return None;
    };
    if matches!(category, kitsu_providers::ProviderAttemptCategory::Success) && *attempt <= 1 {
        return None;
    }
    let category = match category {
        kitsu_providers::ProviderAttemptCategory::Success => "success",
        kitsu_providers::ProviderAttemptCategory::RateLimited => "rate limited",
        kitsu_providers::ProviderAttemptCategory::Unavailable => "unavailable",
        kitsu_providers::ProviderAttemptCategory::Authentication => "authentication",
        kitsu_providers::ProviderAttemptCategory::ClientError => "client error",
        kitsu_providers::ProviderAttemptCategory::ServerError => "server error",
        kitsu_providers::ProviderAttemptCategory::UnexpectedStatus => "unexpected status",
        kitsu_providers::ProviderAttemptCategory::Timeout => "timeout",
        kitsu_providers::ProviderAttemptCategory::Connection => "connection",
        kitsu_providers::ProviderAttemptCategory::ResponseTooLarge => "response too large",
        kitsu_providers::ProviderAttemptCategory::InvalidResponse => "invalid response",
        kitsu_providers::ProviderAttemptCategory::Cancelled => "cancelled",
    };
    let outcome = match outcome {
        kitsu_providers::ProviderAttemptOutcome::ResponseAccepted => "response accepted",
        kitsu_providers::ProviderAttemptOutcome::BodyCompleted => "body completed",
        kitsu_providers::ProviderAttemptOutcome::BodyFailed => "body failed",
        kitsu_providers::ProviderAttemptOutcome::RetryScheduled => "retry scheduled",
        kitsu_providers::ProviderAttemptOutcome::Rejected => "request rejected",
        kitsu_providers::ProviderAttemptOutcome::TransportFailed => "transport failed",
        kitsu_providers::ProviderAttemptOutcome::DeadlineExceeded => "deadline exhausted",
        kitsu_providers::ProviderAttemptOutcome::Cancelled => "cancelled",
    };
    let status = status
        .map(|status| format!("; HTTP {status}"))
        .unwrap_or_default();
    let retry = retry_delay_ms
        .map(|delay| {
            format!(
                "; retry in {delay}ms{}",
                if *retry_after_used {
                    " (Retry-After)"
                } else {
                    ""
                }
            )
        })
        .unwrap_or_default();
    let purpose = match purpose {
        kitsu_core::ProviderRequestPurpose::Inference => "inference",
        kitsu_core::ProviderRequestPurpose::Compaction => "compaction",
        kitsu_core::ProviderRequestPurpose::ModelCatalog => "model catalog",
    };
    let turn_remaining = turn_remaining_ms
        .map(|remaining| format!("; {remaining}ms turn remaining"))
        .unwrap_or_default();
    Some(format!(
        "{purpose} provider attempt {attempt}/{max_attempts}: {category}{status}; {outcome}; terminal={terminal}{retry}; {remaining_deadline_ms}ms provider-request deadline remaining{turn_remaining}"
    ))
}

fn doctor_value<'a>(report: &'a serde_json::Value, pointer: &str) -> &'a str {
    report
        .pointer(pointer)
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unavailable")
}

fn doctor_text(report: &serde_json::Value, pointer: &str) -> String {
    terminal_inline(doctor_value(report, pointer))
}

fn print_doctor_human(report: &serde_json::Value) {
    let config_mark = if report
        .pointer("/config/parse_ok")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        "ok"
    } else {
        "FAIL"
    };
    println!("kitsu {}", doctor_text(report, "/version"));
    println!(
        "[{config_mark}] config ({}) {} — {}",
        doctor_text(report, "/config/source"),
        doctor_text(report, "/config/path_display"),
        doctor_text(report, "/config/status"),
    );
    println!(
        "[info] gateway/model: {}/{}",
        doctor_text(report, "/gateway/name"),
        doctor_text(report, "/gateway/model"),
    );
    println!("[info] auth: {}", doctor_text(report, "/auth/status"),);
    if doctor_value(report, "/provider_route/status") == "bound" {
        println!(
            "[info] provider route: {} / {} / generation {} / {}",
            doctor_text(report, "/provider_route/receipt/route/adapter"),
            doctor_text(report, "/provider_route/receipt/route/wire_revision"),
            report
                .pointer("/provider_route/receipt/route/generation")
                .and_then(serde_json::Value::as_u64)
                .map(|value| value.to_string())
                .unwrap_or_else(|| "unavailable".to_string()),
            doctor_text(report, "/provider_route/receipt/route/profile"),
        );
    } else {
        println!(
            "[info] provider route: {}",
            doctor_text(report, "/provider_route/status"),
        );
    }
    println!(
        "[info] context window: {} tokens ({})",
        report
            .pointer("/context/window")
            .and_then(serde_json::Value::as_u64)
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unavailable".to_string()),
        doctor_text(report, "/context/source"),
    );
    println!(
        "[info] project context: {}",
        doctor_text(report, "/project_context/status"),
    );
    let state_mark = if report
        .pointer("/runtime_state/writable")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        "ok"
    } else {
        "WARN"
    };
    println!(
        "[{state_mark}] runtime state: {} — {}",
        doctor_text(report, "/runtime_state/path_display"),
        doctor_text(report, "/runtime_state/status"),
    );
    let online_status = doctor_text(report, "/online/status");
    let online_scope_note = match (
        report
            .pointer("/online/requested")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
        report
            .pointer("/online/scope")
            .and_then(serde_json::Value::as_str),
        report
            .pointer("/online/status")
            .and_then(serde_json::Value::as_str),
        report
            .pointer("/online/chat_route_probed")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
    ) {
        (true, Some("model_catalog_only"), _, false) => {
            let models = report
                .pointer("/online/models")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0);
            format!(
                "reachable — model catalog only; chat/inference access was not tested ({models} models in catalog)"
            )
        }
        (true, Some("chat_inference"), Some("reachable"), true) => {
            format!("{online_status} — chat/inference accepted one minimal tool-free completion")
        }
        _ => online_status,
    };
    println!("[info] provider check: {online_scope_note}");
    println!(
        "[info] tools: filesystem={} commands={}",
        doctor_text(report, "/tool_policy/filesystem"),
        doctor_text(report, "/tool_policy/commands"),
    );
    println!(
        "[info] automatic artifacts: {} ({}) — oversized tool output {}",
        doctor_text(report, "/artifact_policy/mode"),
        doctor_text(report, "/artifact_policy/source"),
        if report
            .pointer("/artifact_policy/tool_result_offload")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        {
            "may be offloaded"
        } else {
            "is bounded inline"
        },
    );
    let issues = report
        .pointer("/blocking_issues")
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    if issues.is_empty()
        && report
            .pointer("/online/scope")
            .and_then(serde_json::Value::as_str)
            == Some("chat_inference")
        && report
            .pointer("/online/status")
            .and_then(serde_json::Value::as_str)
            == Some("reachable")
    {
        println!(
            "doctor: inference probe succeeded — the configured chat route accepted this model"
        );
    } else if issues.is_empty() {
        // Doctor never sends a chat completion: even an authenticated catalog
        // success cannot prove inference permission. Name both the clean scope
        // and the next verification step without claiming the user is ready.
        println!("doctor: no blocking issues found — run `kitsu` to verify chat/inference access");
    } else {
        println!("doctor: {} blocking issue(s)", issues.len());
        for issue in issues {
            if let Some(issue) = issue.as_str() {
                println!("  - {}", terminal_inline(issue));
            }
        }
    }
}

async fn minimal_inference_probe(
    provider: &ProviderRouteHandle<CompiledProvider>,
    model: &str,
) -> Result<(), ProviderError> {
    use futures::StreamExt as _;

    let request = ChatRequest {
        model: model.to_string(),
        messages: vec![ChatMessage::user("Reply OK.")],
        tools: None,
        // Native Messages is streaming-only. Choose from the immutable route
        // identity, not the mutable gateway label, so this auxiliary request
        // cannot drift onto a different wire than the route it probes.
        stream: provider.identity().adapter()
            == kitsu_providers::ProviderAdapterId::AnthropicMessages,
        temperature: None,
        reasoning_effort: None,
        max_tokens: Some(1),
        response_format: None,
        prompt_cache_key: None,
    };
    let mut response = provider.chat_stream(request).await?;
    let mut finished = false;
    while let Some(delta) = response.next().await {
        if matches!(delta?, ChatDelta::Done(_)) {
            finished = true;
        }
    }
    if finished {
        Ok(())
    } else {
        Err(ProviderError::InvalidResponse(
            "inference probe ended without a terminal marker".to_string(),
        ))
    }
}

fn route_build_cli_error(
    error: CompiledProviderRouteBuildError,
    operation: ProviderOperation<'_>,
    diagnostics: ProviderDiagnosticContext,
) -> CliError {
    match error {
        CompiledProviderRouteBuildError::CompatibleChat(OpenAICompatRouteBuildError::Auth(
            error,
        ))
        | CompiledProviderRouteBuildError::AnthropicMessages(
            AnthropicMessagesRouteBuildError::Auth(error),
        ) => map_provider_error_with_diagnostics(
            ProviderError::Auth(error),
            operation,
            None,
            diagnostics,
        ),
        CompiledProviderRouteBuildError::Contract(error)
        | CompiledProviderRouteBuildError::CompatibleChat(OpenAICompatRouteBuildError::Contract(
            error,
        ))
        | CompiledProviderRouteBuildError::AnthropicMessages(
            AnthropicMessagesRouteBuildError::Contract(error),
        ) => CliError::user(format!("config error: invalid provider route: {error}")),
        error => CliError::user(format!("config error: {error}")),
    }
}

fn compiled_provider_route_config(
    gateway: &Gateway,
    declaration: ProviderRouteDeclaration,
    model: String,
    auth_source: ProviderAuthSource,
    policy: ProviderRoutePolicy,
) -> CompiledProviderRouteConfig {
    match gateway.adapter {
        GatewayAdapter::CompatibleChat => {
            CompiledProviderRouteConfig::CompatibleChat(OpenAICompatRouteConfig {
                declaration,
                model,
                auth_source,
                base_url: gateway.base_url.clone(),
                chat_path: gateway.chat_path.clone(),
                models_path: gateway.models_path.clone().filter(|path| !path.is_empty()),
                policy,
            })
        }
        GatewayAdapter::AnthropicMessages => {
            CompiledProviderRouteConfig::AnthropicMessages(AnthropicMessagesRouteConfig {
                declaration,
                model,
                auth_source,
                base_url: gateway.base_url.clone(),
                messages_path: gateway.chat_path.clone(),
                policy,
            })
        }
    }
}

fn build_inference_management_route(
    config_path: &std::path::Path,
    gateway_name: &str,
    gateway: &Gateway,
    model: String,
    auth_source: ProviderAuthSource,
    auth: &dyn AuthProvider,
    timeout: Duration,
) -> Result<ProviderRouteHandle<CompiledProvider>, CompiledProviderRouteBuildError> {
    let models_path = gateway.models_path.clone().filter(|path| !path.is_empty());
    let catalog_policy = if models_path.is_some() {
        ProviderCatalogPolicy::Configured
    } else {
        ProviderCatalogPolicy::Unavailable
    };
    let declaration = current_provider_route_declaration(config_path, gateway_name, gateway)?;
    let policy = ProviderRoutePolicy::new(0, 0, timeout, timeout, timeout, catalog_policy)?;
    let route_config =
        compiled_provider_route_config(gateway, declaration, model, auth_source, policy);
    let snapshot = build_compiled_provider_route(route_config, auth)?;
    ProviderRouteCurrent::new(snapshot)
        .bind()
        .map_err(Into::into)
}

fn build_catalog_management_route(
    config_path: &std::path::Path,
    gateway_name: &str,
    gateway: &Gateway,
    models_path: String,
    auth_source: ProviderAuthSource,
    auth: &dyn AuthProvider,
    timeout: Duration,
) -> Result<ProviderCatalogHandle<CompiledProvider>, CompiledProviderRouteBuildError> {
    if gateway.adapter == GatewayAdapter::AnthropicMessages {
        return Err(CompiledProviderRouteBuildError::AnthropicMessagesCatalogUnsupported);
    }
    let declaration = current_provider_catalog_route_declaration(config_path, gateway_name)?;
    let policy = ProviderRoutePolicy::new(
        0,
        0,
        timeout,
        timeout,
        timeout,
        ProviderCatalogPolicy::Configured,
    )?;
    let snapshot = build_compiled_catalog_route(
        OpenAICompatCatalogRouteConfig {
            declaration,
            auth_source,
            base_url: gateway.base_url.clone(),
            chat_path: gateway.chat_path.clone(),
            models_path,
            policy,
        },
        auth,
    )?;
    ProviderRouteCurrent::new(snapshot)
        .bind_catalog()
        .map_err(Into::into)
}

async fn run_doctor(cli: &Cli, online: bool, inference: bool, json: bool) -> Result<(), CliError> {
    reject_jsonl_for_management(cli, "kitsu doctor --json")?;
    let config_path = Config::resolve_path(cli.config.as_deref());
    let config_exists = std::fs::symlink_metadata(&config_path).is_ok();
    let config_is_file = config_path.is_file();
    let state_dir = runtime_state_dir_read_only(&config_path);
    let mut runtime_state = runtime_state_diagnostic(&state_dir);
    if let Some(object) = runtime_state.as_object_mut() {
        object.insert(
            "path_display".to_string(),
            serde_json::Value::String(shorten_home(&state_dir)),
        );
    }
    let mut issues = Vec::<String>::new();
    let mut gateway_report = serde_json::json!({
        "name": "unavailable",
        "model": "unavailable",
        "flavor": "unavailable",
        "endpoint": "unavailable",
    });
    let mut auth_report = serde_json::json!({
        "method": "unavailable",
        "credential_present": null,
        "credential_required": null,
        "recovery_hint": null,
        "status": "unavailable until config and gateway are valid",
    });
    let cache_path = context_window_cache_path(&state_dir);
    let mut context_report = serde_json::json!({
        "window": DEFAULT_CONTEXT_WINDOW,
        "source": "conservative default",
        "cache_path": cache_path,
    });
    let project_source = std::env::current_dir()
        .ok()
        .and_then(|directory| llms::discover(&directory, None));
    let project_report = if project_context_disabled(cli) {
        serde_json::json!({"enabled": false, "status": "disabled by flag or environment"})
    } else if let Some(source) = project_source {
        serde_json::json!({
            "enabled": true,
            "status": format!("will load {}", shorten_home(&source)),
            "source": source,
        })
    } else {
        serde_json::json!({"enabled": true, "status": "no llms.txt, AGENTS.md, or CLAUDE.md found"})
    };
    let provider_check_requested = online || inference;
    let provider_check_scope = if inference {
        "chat_inference"
    } else {
        "model_catalog_only"
    };
    let mut provider_route_report = serde_json::json!({
        "status": if provider_check_requested {
            "not_constructed"
        } else {
            "not_constructed_offline"
        },
        "receipt": null,
    });
    let mut online_report = serde_json::json!({
        "requested": provider_check_requested,
        "scope": provider_check_scope,
        "chat_route_probed": false,
        "potentially_billable": inference,
        "request_sent": false,
        "status": if provider_check_requested { "not run" } else { "not requested (offline default)" },
    });

    let config = if !config_exists {
        issues.push(format!(
            "config does not exist at {} (run kitsu init)",
            config_path.display()
        ));
        None
    } else if !config_is_file {
        issues.push(format!(
            "config path {} is not a readable file",
            config_path.display()
        ));
        None
    } else {
        match Config::load(&config_path) {
            Ok(config) => Some(config),
            Err(error) => {
                issues.push(safe_config_error(&error));
                None
            }
        }
    };
    let parse_ok = config.is_some();
    let config_status = if !config_exists {
        "missing"
    } else if parse_ok {
        "parsed successfully"
    } else {
        "parse/read failed"
    };

    if let Some(config) = config.as_ref() {
        match config.select_gateway(cli.gateway.as_deref()) {
            Ok((gateway_name, gateway)) => {
                let provider_diagnostics =
                    ProviderDiagnosticContext::from_gateway(gateway_name, gateway);
                let flavor_ok = match gateway.validate_flavor() {
                    Ok(()) => true,
                    Err(error) => {
                        issues.push(error.to_string());
                        false
                    }
                };
                let model = match gateway.resolve_model(cli.model.as_deref()) {
                    Ok(model) => Some(model),
                    Err(error) => {
                        issues.push(error.to_string());
                        None
                    }
                };
                gateway_report = serde_json::json!({
                    "name": gateway_name,
                    "model": model.as_deref().unwrap_or("unavailable"),
                    "flavor": gateway.flavor,
                    "flavor_valid": flavor_ok,
                    "endpoint": redact_endpoint(&format!("{}{}", gateway.base_url, gateway.chat_path)),
                    "models_path_configured": gateway.models_path.as_deref().is_some_and(|path| !path.is_empty()),
                });

                let auth_valid = match gateway.validate_auth() {
                    Ok(()) => true,
                    Err(error) => {
                        issues.push(error.to_string());
                        false
                    }
                };
                let managed_token = if auth_valid && gateway.auth.method == "bearer-env" {
                    match managed_credential(&state_dir, gateway_name, gateway) {
                        Ok(token) => token,
                        Err(error) => {
                            issues.push(error.to_string());
                            None
                        }
                    }
                } else {
                    None
                };
                let environment_present = environment_override_present(gateway);
                let managed_present = managed_token.is_some();
                let (credential_present, auth_status) = match gateway.auth.method.as_str() {
                    "none" => (None, "no credential required".to_string()),
                    "bearer-env" => {
                        let present = environment_present || managed_present;
                        if auth_valid && !present {
                            issues.push(format!(
                                "no usable credential is available from {} or `kitsu auth login`{}",
                                gateway.auth.env,
                                auth_refresh_hint_suffix(gateway.auth.refresh_hint.as_deref())
                            ));
                        }
                        (
                            Some(present),
                            format!(
                                "bearer credential is {} (source: {})",
                                if present { "present" } else { "missing" },
                                if environment_present {
                                    "environment"
                                } else if managed_present {
                                    "managed"
                                } else {
                                    "missing"
                                }
                            ),
                        )
                    }
                    "static" => {
                        let present = gateway
                            .auth
                            .token
                            .as_deref()
                            .is_some_and(|token| !token.trim().is_empty());
                        (
                            Some(present),
                            if present {
                                "static credential is configured (value hidden)".to_string()
                            } else {
                                "static credential is missing".to_string()
                            },
                        )
                    }
                    other => (Some(false), format!("unsupported auth method {other}")),
                };
                let auth_locally_usable = auth_valid
                    && build_auth(gateway, gateway_name, managed_token.clone())
                        .is_ok_and(|auth| auth.header().is_ok());
                if auth_valid && credential_present != Some(false) && !auth_locally_usable {
                    issues.push(
                        "the effective credential is present but malformed; replace the environment value or run `kitsu auth login`"
                            .to_string(),
                    );
                }
                let recovery_hint = (credential_present == Some(false))
                    .then(|| safe_auth_refresh_hint(gateway.auth.refresh_hint.as_deref()))
                    .flatten();
                auth_report = serde_json::json!({
                    "method": gateway.auth.method,
                    "env": if gateway.auth.method == "bearer-env" {
                        Some(gateway.auth.env.as_str())
                    } else {
                        None
                    },
                    "credential_present": credential_present,
                    "credential_required": gateway.auth.method != "none",
                    "environment_override_present": environment_present,
                    "managed_credential_present": managed_present,
                    "effective_source": if gateway.auth.method == "bearer-env" {
                        if environment_present { "environment" } else if managed_present { "managed" } else { "missing" }
                    } else if gateway.auth.method == "static" { "static" } else { "none" },
                    "recovery_hint": recovery_hint,
                    "valid": auth_valid,
                    "locally_usable": auth_locally_usable,
                    "status": auth_status,
                });

                if let Some(model) = model.as_deref() {
                    let (window, source) = if let Some(window) = cli.context_window {
                        (window, "--context-window")
                    } else if let Some(window) = gateway.context_window {
                        (window, "gateway profile")
                    } else {
                        let key = context_window_cache_key(
                            &gateway.base_url,
                            gateway.models_path.as_deref(),
                            model,
                        );
                        match read_cached_context_window(&cache_path, &key) {
                            Some(window) => (window, "fresh discovery cache"),
                            None => (DEFAULT_CONTEXT_WINDOW, "conservative default"),
                        }
                    };
                    context_report = serde_json::json!({
                        "window": window,
                        "source": source,
                        "cache_path": cache_path,
                    });
                }

                if inference {
                    if !flavor_ok
                        || !auth_valid
                        || !auth_locally_usable
                        || credential_present == Some(false)
                        || model.is_none()
                    {
                        let issue = "inference provider check was requested but skipped: fix gateway, model, or auth diagnostics first".to_string();
                        issues.push(issue.clone());
                        online_report = serde_json::json!({
                            "requested": true,
                            "scope": "chat_inference",
                            "chat_route_probed": false,
                            "potentially_billable": true,
                            "request_sent": false,
                            "status": issue,
                        });
                    } else {
                        let auth_source =
                            current_provider_auth_source(gateway, managed_token.is_some());
                        let auth = build_auth(gateway, gateway_name, managed_token.clone())
                            .map_err(|error| CliError::user(safe_config_error(&error)))?;
                        let provider = build_inference_management_route(
                            &config_path,
                            gateway_name,
                            gateway,
                            model.clone().expect("validated above"),
                            auth_source,
                            auth.as_ref(),
                            Duration::from_secs(cli.timeout_secs),
                        )
                        .map_err(|error| {
                            route_build_cli_error(
                                error,
                                ProviderOperation::InferenceProbe {
                                    model: model.as_deref().expect("validated above"),
                                },
                                provider_diagnostics,
                            )
                        })?;
                        provider_route_report = serde_json::json!({
                            "status": "bound",
                            "receipt": provider.receipt(),
                        });
                        let effective_model = model.as_deref().expect("validated above");
                        match await_cancellable(minimal_inference_probe(&provider, effective_model))
                            .await
                        {
                            Some(Ok(())) => {
                                online_report = serde_json::json!({
                                    "requested": true,
                                    "scope": "chat_inference",
                                    "chat_route_probed": true,
                                    "potentially_billable": true,
                                    "request_sent": true,
                                    "status": "reachable",
                                    "effective_model": effective_model,
                                });
                            }
                            Some(Err(error)) => {
                                let safe = safe_provider_error_message(
                                    &error,
                                    ProviderOperation::InferenceProbe {
                                        model: effective_model,
                                    },
                                    Some(cli.timeout_secs),
                                    provider_diagnostics,
                                );
                                issues.push(format!("inference provider check failed: {safe}"));
                                online_report = serde_json::json!({
                                    "requested": true,
                                    "scope": "chat_inference",
                                    "chat_route_probed": true,
                                    "potentially_billable": true,
                                    "request_sent": true,
                                    "status": safe,
                                    "effective_model": effective_model,
                                });
                            }
                            None => {
                                return Err(CliError::cancelled(
                                    "doctor inference probe cancelled by Ctrl+C",
                                ));
                            }
                        }
                    }
                } else if online {
                    let models_path = gateway.models_path.clone().filter(|path| !path.is_empty());
                    match models_path {
                        None => {
                            let issue = "online provider check was requested but skipped: no models_path is configured for a safe read-only probe".to_string();
                            issues.push(issue.clone());
                            online_report = serde_json::json!({
                                "requested": true,
                                "scope": "model_catalog_only",
                                "chat_route_probed": false,
                                "potentially_billable": false,
                                "request_sent": false,
                                "status": issue,
                            });
                        }
                        Some(_)
                            if !flavor_ok
                                || !auth_valid
                                || !auth_locally_usable
                                || credential_present == Some(false) =>
                        {
                            let issue = "online provider check was requested but skipped: fix gateway or auth diagnostics first".to_string();
                            issues.push(issue.clone());
                            online_report = serde_json::json!({
                                "requested": true,
                                "scope": "model_catalog_only",
                                "chat_route_probed": false,
                                "potentially_billable": false,
                                "request_sent": false,
                                "status": issue,
                            });
                        }
                        Some(models_path) => {
                            let auth_source =
                                current_provider_auth_source(gateway, managed_token.is_some());
                            let auth = build_auth(gateway, gateway_name, managed_token.clone())
                                .map_err(|error| CliError::user(safe_config_error(&error)))?;
                            let provider = build_catalog_management_route(
                                &config_path,
                                gateway_name,
                                gateway,
                                models_path,
                                auth_source,
                                auth.as_ref(),
                                Duration::from_secs(cli.timeout_secs),
                            )
                            .map_err(|error| {
                                route_build_cli_error(
                                    error,
                                    ProviderOperation::ModelCatalog,
                                    provider_diagnostics,
                                )
                            })?;
                            provider_route_report = serde_json::json!({
                                "status": "bound",
                                "receipt": provider.receipt(),
                            });
                            match await_cancellable(provider.list_models()).await {
                                Some(Ok(Some(models))) => {
                                    let effective_model = model.as_deref();
                                    let effective_model_available = effective_model.map(|model| {
                                        model_catalog_advertises_selected_model(
                                            model,
                                            &models,
                                            provider_diagnostics,
                                        )
                                    });
                                    let models = normalize_model_catalog(models);
                                    if effective_model_available == Some(false) {
                                        issues.push(format!(
                                        "effective model '{}' is not advertised by the normalized gateway catalog",
                                        terminal_inline(effective_model.expect("checked above"))
                                    ));
                                    }
                                    online_report = serde_json::json!({
                                        "requested": true,
                                        "scope": "model_catalog_only",
                                        "chat_route_probed": false,
                                        "potentially_billable": false,
                                        "request_sent": true,
                                        "status": "reachable",
                                        "models": models.len(),
                                        "effective_model": effective_model,
                                        "effective_model_available": effective_model_available,
                                    });
                                }
                                Some(Ok(None)) => {
                                    let issue = "online provider check was requested but skipped: provider has no model catalog".to_string();
                                    issues.push(issue.clone());
                                    online_report = serde_json::json!({
                                        "requested": true,
                                        "scope": "model_catalog_only",
                                        "chat_route_probed": false,
                                        "potentially_billable": false,
                                        "request_sent": true,
                                        "status": issue,
                                    });
                                }
                                Some(Err(error)) => {
                                    let safe = safe_provider_error_message(
                                        &error,
                                        ProviderOperation::ModelCatalog,
                                        Some(cli.timeout_secs),
                                        provider_diagnostics,
                                    );
                                    let reason = bounded_model_catalog_reason(&error);
                                    issues.push(format!("online provider check failed: {safe}"));
                                    online_report = serde_json::json!({
                                        "requested": true,
                                        "scope": "model_catalog_only",
                                        "chat_route_probed": false,
                                        "potentially_billable": false,
                                        "request_sent": true,
                                        "status": safe,
                                        "reason": reason,
                                    });
                                }
                                None => {
                                    return Err(CliError::cancelled(
                                        "doctor provider check cancelled by Ctrl+C",
                                    ));
                                }
                            }
                        }
                    }
                }
            }
            Err(error) => issues.push(error.to_string()),
        }
    }

    let filesystem_policy = if cli.dangerously_skip_permissions {
        "DANGER: unattended bypass — global non-protected filesystem access AND auto-approved commands inside their roots"
    } else if cli.dangerously_allow_all_filesystem {
        "DANGER: global non-protected filesystem bypass when tools are enabled"
    } else if cli.yes {
        "non-prompting and confined to explicit/current roots when tools are enabled"
    } else {
        "interactive chat prompts; automation is deny-by-default unless roots are granted"
    };
    let (artifact_policy, artifact_policy_source) = if cli.no_artifacts {
        (ArtifactStoragePolicy::InlineOnly, ArtifactPolicySource::Cli)
    } else {
        match config.as_ref().and_then(|config| config.artifact_storage) {
            Some(false) => (
                ArtifactStoragePolicy::InlineOnly,
                ArtifactPolicySource::Config,
            ),
            Some(true) => (
                ArtifactStoragePolicy::Automatic,
                ArtifactPolicySource::Config,
            ),
            None => (
                ArtifactStoragePolicy::Automatic,
                ArtifactPolicySource::Default,
            ),
        }
    };
    let report = serde_json::json!({
        "version": cli::LONG_VERSION,
        "read_only": true,
        "config": {
            "source": config_resolution_source(cli),
            "path": config_path,
            "path_display": shorten_home(&config_path),
            "exists": config_exists,
            "regular_file": config_is_file,
            "parse_ok": parse_ok,
            "status": config_status,
        },
        "gateway": gateway_report,
        "auth": auth_report,
        "provider_route": provider_route_report,
        "context": context_report,
        "project_context": project_report,
        "runtime_state": runtime_state,
        "online": online_report,
        "tool_policy": {
            "filesystem": filesystem_policy,
            "commands": "disabled unless explicitly enabled; enabled commands require exact approval plus mandatory fail-closed OS containment",
            "scripted_tools": "not registered unless a filesystem capability or command policy is explicit",
        },
        "artifact_policy": artifact_policy_receipt(
            artifact_policy,
            artifact_policy_source,
            false,
        ),
        "blocking_issues": issues,
    });
    if json {
        print_json(&report)?;
    } else {
        print_doctor_human(&report);
    }
    let failures = report
        .pointer("/blocking_issues")
        .and_then(serde_json::Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    if failures == 0 {
        Ok(())
    } else {
        Err(CliError::user(format!(
            "doctor found {failures} blocking issue(s)"
        )))
    }
}

/// Provider + model + auth resolved from config and CLI flags. Shared by the
/// `ask` and `chat` commands so they construct the gateway connection identically.
struct ChatSetup {
    /// Atomic owner of the current immutable generation. `ask`/`chat` bind a
    /// request-facing handle from this owner; raw inference/catalog runtimes do
    /// not leave composition.
    provider_route: ProviderRouteCurrent<CompiledProvider>,
    gateway_name: String,
    provider_diagnostics: ProviderDiagnosticContext,
    config_path: std::path::PathBuf,
    state_dir: std::path::PathBuf,
    endpoint: String,
    auth_status: String,
    /// Config-level opt-out for the model-callable `workspace_diff` evidence
    /// tool (docs/workspace-diff-tool.md). Defaults to enabled.
    workspace_evidence: bool,
    /// Config-level per-turn subagent spawn cap (`agent_spawn_cap`). `None`
    /// falls back to the mode default (interactive 8, scripted/piped 2);
    /// `--agent-spawn-cap` overrides.
    agent_spawn_cap: Option<u32>,
    /// Config-level `[agents] state_file` mode deciding whether this process
    /// publishes the per-process agent state hint file.
    agent_state_file: crate::config::StateFileMode,
    /// Config-level `[agents] blocking` mode: how a background agent's
    /// ungranted permission request is handled (design B1).
    agent_blocking: crate::config::AgentBlockingMode,
    /// Config-level `[agents] block_timeout_secs`, already typed (B3).
    agent_block_timeout: std::time::Duration,
    /// Config-level `[hooks] on_agent_state` command, already split into argv
    /// (requirement H3). `None` when absent, empty, or unsplittable, so an
    /// unusable command is a no-op rather than a per-boundary parse attempt.
    agent_state_hook: Option<Vec<String>>,
    /// The config-level `[tui]` table (design §4.8), already defaulted. Held
    /// whole rather than as a resolved mode: the flags that override it are
    /// read where the renderer is installed, so there is one resolution point
    /// instead of one per key.
    tui: crate::config::TuiConfig,
    /// Effective run-level policy for Kitsu-created automatic output
    /// artifacts. This never changes explicit session, credential, `-o`, or
    /// model filesystem destinations.
    artifact_policy: ArtifactStoragePolicy,
    artifact_policy_source: ArtifactPolicySource,
    /// Resolved model context window in tokens, if known (design §3.2 order:
    /// `--context-window` → profile `context_window` → `/v1/models` → unset).
    context_window: Option<u64>,
    /// True when `context_window` came from an explicit `--context-window` flag
    /// or the gateway profile's `context_window`, rather than `/v1/models`
    /// discovery. A pinned window is a user/config declaration that overrides
    /// "any value discovered from `/v1/models`" (see the flag's doc comment) —
    /// `/model` must not silently replace it with fresh auto-discovery.
    context_window_pinned: bool,
    /// Human-readable, secret-free provenance for the effective context
    /// window. The background cold-cache probe updates only its discovery
    /// state; the conservative current-run budget remains unchanged.
    context_window_provenance: Arc<std::sync::Mutex<ContextWindowProvenance>>,
    context_window_refresh: ContextWindowRefreshConfig,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ArtifactPolicySource {
    Default,
    Config,
    Cli,
}

impl ArtifactPolicySource {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Default => "default",
            Self::Config => "config",
            Self::Cli => "cli",
        }
    }
}

fn artifact_policy_receipt(
    policy: ArtifactStoragePolicy,
    source: ArtifactPolicySource,
    model_read_root_granted: bool,
) -> serde_json::Value {
    let automatic = policy == ArtifactStoragePolicy::Automatic;
    serde_json::json!({
        "mode": if automatic { "automatic" } else { "disabled" },
        "source": source.as_str(),
        "new_automatic_artifact_writes": automatic,
        "command_output_persistence": automatic,
        "tool_result_offload": automatic,
        "existing_artifacts_unchanged": !automatic,
        "model_artifact_read_root_granted": automatic && model_read_root_granted,
    })
}

#[derive(Clone)]
struct ContextWindowRefreshConfig {
    cache_path: std::path::PathBuf,
    base_url: String,
    models_path: Option<String>,
}

impl ContextWindowRefreshConfig {
    fn cache_key(&self, model: &str) -> String {
        context_window_cache_key(&self.base_url, self.models_path.as_deref(), model)
    }

    fn enabled(&self) -> bool {
        self.models_path.is_some()
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ContextWindowSource {
    Cli,
    Profile,
    DiskCache,
    LiveDiscovery,
    ServedWindow,
    ConservativeDefault,
}

impl ContextWindowSource {
    fn label(&self) -> &'static str {
        match self {
            Self::Cli => "CLI --context-window",
            Self::Profile => "gateway profile context_window",
            Self::DiskCache => "disk cache",
            Self::LiveDiscovery => "live model discovery",
            Self::ServedWindow => "runtime-served window (clamped)",
            Self::ConservativeDefault => "conservative default",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ContextWindowCacheState {
    NotConsulted,
    Miss,
    Unreadable,
    WriteFailed,
    Fresh { age_secs: u64, ttl_secs: u64 },
    Stale { age_secs: u64, ttl_secs: u64 },
}

impl ContextWindowCacheState {
    fn label(&self) -> String {
        match self {
            Self::NotConsulted => "not consulted".to_string(),
            Self::Miss => "cold (no entry)".to_string(),
            Self::Unreadable => "cold (cache unreadable or invalid)".to_string(),
            Self::WriteFailed => "cache write failed".to_string(),
            Self::Fresh { age_secs, ttl_secs } => format!(
                "fresh (age {}; TTL {})",
                compact_duration(*age_secs),
                compact_duration(*ttl_secs)
            ),
            Self::Stale { age_secs, ttl_secs } => format!(
                "stale (age {}; TTL {})",
                compact_duration(*age_secs),
                compact_duration(*ttl_secs)
            ),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ContextWindowDiscoveryState {
    NotNeeded,
    Disabled,
    Pending,
    ReadyForNextRun { window: u64 },
    CompleteButNotCached { window: u64 },
    FinishedWithoutMetadata,
    LiveComplete,
}

impl ContextWindowDiscoveryState {
    fn label(&self) -> String {
        match self {
            Self::NotNeeded => "not needed".to_string(),
            Self::Disabled => "disabled (models_path is not configured)".to_string(),
            Self::Pending => {
                "in progress (current run keeps the default; result applies next run)".to_string()
            }
            Self::ReadyForNextRun { window } => format!(
                "complete ({window} tokens cached for the next run; current run keeps the default)"
            ),
            Self::CompleteButNotCached { window } => format!(
                "complete ({window} tokens discovered, but the private cache write failed; current run keeps the default)"
            ),
            Self::FinishedWithoutMetadata => {
                "finished without usable metadata (or the advisory request failed)".to_string()
            }
            Self::LiveComplete => "complete for the current model".to_string(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ContextWindowProvenance {
    source: ContextWindowSource,
    cache: ContextWindowCacheState,
    discovery: ContextWindowDiscoveryState,
}

impl ContextWindowProvenance {
    fn pinned(source: ContextWindowSource) -> Self {
        Self {
            source,
            cache: ContextWindowCacheState::NotConsulted,
            discovery: ContextWindowDiscoveryState::NotNeeded,
        }
    }

    fn cached(age_secs: u64) -> Self {
        Self {
            source: ContextWindowSource::DiskCache,
            cache: ContextWindowCacheState::Fresh {
                age_secs,
                ttl_secs: CONTEXT_WINDOW_CACHE_TTL_SECS,
            },
            discovery: ContextWindowDiscoveryState::NotNeeded,
        }
    }

    fn defaulted(cache: ContextWindowCacheState, discovery: ContextWindowDiscoveryState) -> Self {
        Self {
            source: ContextWindowSource::ConservativeDefault,
            cache,
            discovery,
        }
    }

    fn live_discovery(window: Option<u64>) -> Self {
        match window {
            Some(_) => Self {
                source: ContextWindowSource::LiveDiscovery,
                cache: ContextWindowCacheState::NotConsulted,
                discovery: ContextWindowDiscoveryState::LiveComplete,
            },
            None => Self::defaulted(
                ContextWindowCacheState::NotConsulted,
                ContextWindowDiscoveryState::FinishedWithoutMetadata,
            ),
        }
    }

    fn refreshed(cache_written: bool) -> Self {
        Self {
            source: ContextWindowSource::LiveDiscovery,
            cache: if cache_written {
                ContextWindowCacheState::Fresh {
                    age_secs: 0,
                    ttl_secs: CONTEXT_WINDOW_CACHE_TTL_SECS,
                }
            } else {
                ContextWindowCacheState::WriteFailed
            },
            discovery: ContextWindowDiscoveryState::LiveComplete,
        }
    }
}

fn compact_duration(seconds: u64) -> String {
    if seconds < 60 {
        format!("{seconds}s")
    } else if seconds < 60 * 60 {
        format!("{}m", seconds / 60)
    } else if seconds < 24 * 60 * 60 {
        let hours = seconds / (60 * 60);
        let minutes = (seconds % (60 * 60)) / 60;
        if minutes == 0 {
            format!("{hours}h")
        } else {
            format!("{hours}h {minutes}m")
        }
    } else {
        let days = seconds / (24 * 60 * 60);
        let hours = (seconds % (24 * 60 * 60)) / (60 * 60);
        if hours == 0 {
            format!("{days}d")
        } else {
            format!("{days}d {hours}h")
        }
    }
}

fn project_context_disabled(cli: &Cli) -> bool {
    cli.no_project_context || std::env::var_os("KITSU_NO_PROJECT_CONTEXT").is_some()
}

/// Concatenate the bodies of the skills named via `--skill` into one context
/// block (or `None` if none/unknown). Unknown names warn and are skipped.
fn preload_skills(cli: &Cli, skillset: &skills::SkillSet) -> Option<String> {
    if cli.skill.is_empty() {
        return None;
    }
    let mut out = String::new();
    for name in &cli.skill {
        match skillset.load_with_snapshot(name) {
            Ok(loaded) => out.push_str(&format!("{}\n\n", loaded.text)),
            Err(error) => eprintln!(
                "~ cannot preload skill '{}': {} (skipped)",
                terminal_inline(name),
                terminal_inline(&error.to_string())
            ),
        }
    }
    let out = out.trim().to_string();
    if out.is_empty() {
        None
    } else {
        eprintln!("~ preloaded {} skill(s)", cli.skill.len());
        Some(out)
    }
}

const LOADED_SKILL_PREFIX: &str = "[Loaded skill: ";
const SKILL_SNAPSHOT_PREFIX: &str = "[Skill snapshot: ";

fn loaded_skill_name(content: &str) -> Option<&str> {
    let rest = content.strip_prefix(LOADED_SKILL_PREFIX)?;
    let end = rest.find("]\n")?;
    let name = &rest[..end];
    (!name.is_empty()).then_some(name)
}

fn loaded_skill_snapshot(content: &str) -> Option<skills::SkillContentSnapshot> {
    let snapshot_line = content.lines().nth(1)?;
    let encoded = snapshot_line
        .strip_prefix(SKILL_SNAPSHOT_PREFIX)?
        .strip_suffix(']')?;
    serde_json::from_str(encoded).ok()
}

fn loaded_skill_message(name: &str, loaded: &skills::LoadedSkill) -> ChatMessage {
    match serde_json::to_string(&loaded.snapshot) {
        Ok(snapshot) => ChatMessage::user(format!(
            "{LOADED_SKILL_PREFIX}{name}]\n{SKILL_SNAPSHOT_PREFIX}{snapshot}]\n\n{}",
            loaded.text
        )),
        // A non-UTF-8 host path can make a PathBuf snapshot non-serializable.
        // Retain the bounded loaded text; resume treats this as a legacy record
        // and revalidates it rather than crashing or trusting stale content.
        Err(_) => ChatMessage::user(format!("{LOADED_SKILL_PREFIX}{name}]\n\n{}", loaded.text)),
    }
}

/// Rebuild persisted `/skill` context from current descriptor-pinned sources.
/// Saved skill text is evidence, never authority: missing sources are removed,
/// changed hashes/resources are replaced, and every drift is disclosed.
fn refresh_loaded_skill_messages(
    messages: &mut Vec<ChatMessage>,
    skillset: &skills::SkillSet,
) -> Vec<String> {
    let mut refreshed = Vec::with_capacity(messages.len());
    let mut notices = Vec::new();
    for message in std::mem::take(messages) {
        let Some(name) = (matches!(message.role, kitsu_providers::Role::User))
            .then(|| loaded_skill_name(&message.content))
            .flatten()
        else {
            refreshed.push(message);
            continue;
        };
        match skillset.load_with_snapshot(name) {
            Ok(current) => {
                if let Some(previous) = loaded_skill_snapshot(&message.content) {
                    let drift = previous.drift_from(&current.snapshot);
                    if !drift.is_empty() {
                        notices.push(format!(
                            "refreshed loaded skill '{}' after {} changed",
                            name,
                            drift
                                .iter()
                                .map(|change| change.field.as_str())
                                .collect::<Vec<_>>()
                                .join(", ")
                        ));
                    }
                } else if message.content != loaded_skill_message(name, &current).content {
                    notices.push(format!(
                        "refreshed legacy loaded skill '{}' and captured current provenance",
                        name
                    ));
                }
                refreshed.push(loaded_skill_message(name, &current));
            }
            Err(error) => notices.push(format!("removed saved loaded skill '{}': {}", name, error)),
        }
    }
    *messages = refreshed;
    notices
}

/// Register the base tool set (fs read/write, grep, skill) shared by the main
/// agent and by subagents. `spawn_agent` is registered separately and only for
/// the main agent, so subagents can't spawn further (depth-1).
///
/// `tier` trims the advertised read surface for small context windows — see
/// [`kitsu_tools::ToolTier`]. It changes only what the model is TOLD exists;
/// permissions and every authorization check are identical in both tiers.
// Each parameter is an independent axis of the registry (authority, skills,
// journal, command policy, advertised breadth) that the three call sites vary
// separately; bundling them into a struct would only move the argument list.
#[allow(clippy::too_many_arguments)]
fn register_base_tools(
    tools: &mut Registry,
    perms: &Arc<Permissions>,
    skillset: &Arc<skills::SkillSet>,
    can_read: bool,
    can_write: bool,
    journal: &kitsu_tools::builtins::fs::WriteJournal,
    commands: Option<&Arc<kitsu_tools::CommandPolicy>>,
    tier: kitsu_tools::ToolTier,
) -> Result<(), RegistryError> {
    if can_read {
        builtins::register_fs_tools_tiered(tools, perms.clone(), tier)?;
    }
    if can_write {
        let (descriptor, handler) =
            builtins::fs::write_file_tool_with_journal(perms.clone(), Some(journal.clone()));
        tools.register_with_descriptor(descriptor, handler)?;
    }
    // Exact-text edits necessarily inspect existing content. Do not advertise
    // that read-modify-write primitive for a genuinely write-only invocation.
    if can_read && can_write {
        let (descriptor, handler) =
            builtins::fs::edit_file_tool_with_journal(perms.clone(), Some(journal.clone()));
        tools.register_with_descriptor(descriptor, handler)?;
    }
    if !skillset.is_empty() {
        let (d, h) = skills::skill_tool(skillset.clone());
        tools.register_with_descriptor(d, h)?;
    }
    if let Some(commands) = commands {
        builtins::register_command_tool(tools, commands.clone())?;
    }

    Ok(())
}

fn can_resolve_offload_pointers(tool_names: &[String]) -> bool {
    tool_names.iter().any(|name| name == "fs_read_file")
}

/// Parse the `--compaction` flag into the orchestrator's mode.
fn compaction_mode(cli: &Cli) -> CompactionMode {
    if cli.compaction == "summarize" {
        CompactionMode::Summarize
    } else {
        CompactionMode::Trim
    }
}

fn compaction_mode_name(mode: CompactionMode) -> &'static str {
    match mode {
        CompactionMode::Trim => "trim",
        CompactionMode::Summarize => "summarize",
    }
}

fn compaction_reason_name(reason: kitsu_core::CompactionReason) -> &'static str {
    match reason {
        kitsu_core::CompactionReason::ContextTargetExceeded => "context_target_exceeded",
        kitsu_core::CompactionReason::ManualRequest => "manual_request",
    }
}

fn compaction_outcome_name(outcome: kitsu_core::CompactionOutcome) -> &'static str {
    match outcome {
        kitsu_core::CompactionOutcome::ToolResultsElided => "tool_results_elided",
        kitsu_core::CompactionOutcome::Trimmed => "trimmed",
        kitsu_core::CompactionOutcome::Summarized => "summarized",
        kitsu_core::CompactionOutcome::SummaryFallbackTrim => "summary_fallback_trim",
        kitsu_core::CompactionOutcome::SummaryFallbackNoOp => "summary_fallback_no_op",
    }
}

fn compaction_fallback_name(reason: kitsu_core::SummaryFallbackReason) -> &'static str {
    match reason {
        kitsu_core::SummaryFallbackReason::CircuitBreaker => "circuit_breaker",
        kitsu_core::SummaryFallbackReason::RequestTooLarge => "request_too_large",
        kitsu_core::SummaryFallbackReason::ProviderFailure => "provider_failure",
        kitsu_core::SummaryFallbackReason::EmptyCompletion => "empty_completion",
        kitsu_core::SummaryFallbackReason::IncompleteResponse => "incomplete_response",
        kitsu_core::SummaryFallbackReason::ResponseTooLarge => "response_too_large",
        kitsu_core::SummaryFallbackReason::ContextWindowUnknown => "context_window_unknown",
    }
}

fn compaction_report_payload(report: &kitsu_core::CompactionReport) -> serde_json::Value {
    let record = report.record.as_ref().map(|record| {
        serde_json::json!({
            "sequence": record.sequence,
            "reason": compaction_reason_name(record.reason),
            "configured_mode": compaction_mode_name(record.configured_mode),
            "outcome": compaction_outcome_name(record.outcome),
            "fallback_reason": record.fallback_reason.map(compaction_fallback_name),
            "tokens_before": record.tokens_before,
            "tokens_after": record.tokens_after,
            "messages_before": record.messages_before,
            "messages_after": record.messages_after,
            "tool_results_elided": record.tool_results_elided,
            "exchanges_removed": record.exchanges_removed,
            "summary_input_shortened": record.summary_input_shortened,
            "summary_output_shortened": record.summary_output_shortened,
        })
    });
    serde_json::json!({
        "kind": "compaction",
        "changed": report.changed,
        "target_tokens": report.target_tokens,
        "tokens_before": report.tokens_before,
        "tokens_after": report.tokens_after,
        "tokens_saved": report.tokens_before.saturating_sub(report.tokens_after),
        "record": record,
        "usage": {
            "prompt_tokens": report.usage.prompt_tokens,
            "completion_tokens": report.usage.completion_tokens,
            "total_tokens": report.usage.total_tokens,
        },
    })
}

/// Build the per-turn `AgentConfig` shared by `ask`, scripted runs, and
/// interactive chat, from a single place — so a future field/default change
/// can't silently apply to only some call sites (as `ask`'s hardcoded
/// `offload_dir: None` very nearly diverged from the other two paths).
fn build_agent_config(
    model: String,
    cli: &Cli,
    context_window: Option<u64>,
    offload_dir: Option<std::path::PathBuf>,
    artifact_policy: ArtifactStoragePolicy,
) -> AgentConfig {
    let reasoning_effort = cli_reasoning_effort(cli);
    AgentConfig {
        model,
        request_timeout_ms: Some(cli.timeout_secs.saturating_mul(1_000)),
        turn_deadline: None,
        max_rounds: cli.max_rounds,
        max_context_bytes: 128 * 1024,
        // The CLI's documented conservative default is an enforcement value,
        // not just a display fallback. Keep the session cell as `None` so
        // `/status` can disclose that it was defaulted, but every provider
        // request and manual compaction receives the same checked 8K budget.
        context_window: Some(context_window.unwrap_or(DEFAULT_CONTEXT_WINDOW)),
        offload_dir: (artifact_policy == ArtifactStoragePolicy::Automatic)
            .then_some(offload_dir)
            .flatten(),
        offload_char_cap: cli.offload_cap.map(|cap| cap as usize),
        artifact_policy,
        stream: !cli.no_stream,
        temperature: cli.temperature,
        reasoning_effort,
        max_tokens: cli.max_output_tokens,
        response_format: active_output_schema().map(|schema| JsonSchemaFormat {
            name: "kitsu_output".to_string(),
            schema: schema.value.clone(),
            strict: true,
        }),
        defer_response_format_until_final: false,
        structured_finalization_gate: None,
        compaction: compaction_mode(cli),
        quiet: cli.jsonl,
        event_log: None,
        skill_names: Vec::new(),
        run_tallies: None,
        spawn_budget: None,
    }
}

fn cli_reasoning_effort(cli: &Cli) -> Option<kitsu_providers::ReasoningEffort> {
    cli.reasoning_effort.as_deref().map(|effort| match effort {
        "none" => kitsu_providers::ReasoningEffort::None,
        "minimal" => kitsu_providers::ReasoningEffort::Minimal,
        "low" => kitsu_providers::ReasoningEffort::Low,
        "medium" => kitsu_providers::ReasoningEffort::Medium,
        "high" => kitsu_providers::ReasoningEffort::High,
        "xhigh" => kitsu_providers::ReasoningEffort::XHigh,
        _ => unreachable!("clap validates reasoning effort"),
    })
}

/// The bound a non-interactive exit puts on joining live background agents.
/// Unset means "as long as one model turn is allowed to take", which is the
/// only other deadline the invocation already declared.
fn agent_join_timeout(cli: &Cli) -> std::time::Duration {
    std::time::Duration::from_secs(cli.agent_join_timeout.unwrap_or(cli.timeout_secs))
}

fn reasoning_effort_label(effort: Option<kitsu_providers::ReasoningEffort>) -> &'static str {
    match effort {
        None => "gateway default",
        Some(kitsu_providers::ReasoningEffort::None) => "none",
        Some(kitsu_providers::ReasoningEffort::Minimal) => "minimal",
        Some(kitsu_providers::ReasoningEffort::Low) => "low",
        Some(kitsu_providers::ReasoningEffort::Medium) => "medium",
        Some(kitsu_providers::ReasoningEffort::High) => "high",
        Some(kitsu_providers::ReasoningEffort::XHigh) => "xhigh",
    }
}

/// Removes a stateless run's offload namespace (and every session generation
/// beneath it) when the chat ends, so we don't leak temp dirs into `/tmp`.
struct OffloadDirGuard(std::path::PathBuf);
impl Drop for OffloadDirGuard {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// Allocates a destination that has never carried artifact authority in this
/// process. Session sidecars remain durable, but every `/new` and `/resume`
/// receives a fresh child so resetting runtime grants cannot be undone by
/// granting the same directory again.
#[derive(Debug, Default)]
struct ArtifactDirectoryAllocator {
    next_generation: u64,
    /// Advisory locks held for the lifetime of this process, one per allocated
    /// generation. Cross-run pruning tests these instead of pids (which are
    /// reused) or marker files (which a killed process never removes); the
    /// kernel releases them on process death, including `SIGKILL`.
    locks: Vec<std::fs::File>,
}

impl ArtifactDirectoryAllocator {
    fn allocate(&mut self, base: &std::path::Path) -> Result<std::path::PathBuf, String> {
        std::fs::create_dir_all(base).map_err(|error| {
            format!(
                "cannot create artifact namespace {}: {error}",
                base.display()
            )
        })?;
        let metadata = std::fs::symlink_metadata(base).map_err(|error| {
            format!(
                "cannot inspect artifact namespace {}: {error}",
                base.display()
            )
        })?;
        if metadata.file_type().is_symlink() || !metadata.file_type().is_dir() {
            return Err(format!(
                "artifact namespace '{}' is not a regular directory",
                base.display()
            ));
        }

        for _ in 0..256 {
            let generation = self.next_generation;
            self.next_generation = self
                .next_generation
                .checked_add(1)
                .ok_or_else(|| "artifact generation counter exhausted".to_string())?;
            let directory = base.join(format!("runtime-{}-{generation}", run_id()));
            match std::fs::create_dir(&directory) {
                Ok(()) => {
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt as _;
                        if let Err(error) = std::fs::set_permissions(
                            &directory,
                            std::fs::Permissions::from_mode(0o700),
                        ) {
                            let _ = std::fs::remove_dir(&directory);
                            return Err(format!(
                                "cannot secure artifact directory {}: {error}",
                                directory.display()
                            ));
                        }
                    }
                    if let Some(lock) = artifacts::hold_generation_lock(&directory) {
                        self.locks.push(lock);
                    }
                    return Ok(directory);
                }
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(error) => {
                    return Err(format!(
                        "cannot create artifact directory {}: {error}",
                        directory.display()
                    ));
                }
            }
        }
        Err(format!(
            "cannot allocate a fresh artifact directory under {}",
            base.display()
        ))
    }
}

/// `/help` section a command belongs to. Grouping is presentation only: the
/// registry below stays the single source for completion and JSONL payloads.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CommandGroup {
    Session,
    ContextHistory,
    FilesDiffsCheckpoints,
    AgentsJobs,
    Permissions,
    ModelsReasoning,
}

impl CommandGroup {
    const ORDER: [CommandGroup; 6] = [
        CommandGroup::Session,
        CommandGroup::ContextHistory,
        CommandGroup::FilesDiffsCheckpoints,
        CommandGroup::AgentsJobs,
        CommandGroup::Permissions,
        CommandGroup::ModelsReasoning,
    ];

    fn heading(self) -> &'static str {
        match self {
            CommandGroup::Session => "session",
            CommandGroup::ContextHistory => "context & history",
            CommandGroup::FilesDiffsCheckpoints => "files, diffs & checkpoints",
            CommandGroup::AgentsJobs => "agents & jobs",
            CommandGroup::Permissions => "permissions",
            CommandGroup::ModelsReasoning => "models & reasoning",
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct SlashCommandSpec {
    name: &'static str,
    args: &'static str,
    description: &'static str,
    /// Longer explanation for `/help <command>`: behavior, constraints, and
    /// an example where one helps. Empty falls back to `description`.
    details: &'static str,
    group: CommandGroup,
    /// A backward-compatible alias folds into its parent's `/help` row while
    /// remaining a first-class registry entry for completion and dispatch.
    alias_of: Option<&'static str>,
}

impl SlashCommandSpec {
    fn syntax(self) -> String {
        if self.args.is_empty() {
            format!("/{}", self.name)
        } else {
            format!("/{} {}", self.name, self.args)
        }
    }
}

