    #[test]
    fn composer_surfaces_fit_terminal_columns_and_unicode_cell_widths() {
        use unicode_width::UnicodeWidthStr as _;

        assert_eq!(composer_surface_inner_width(None), 68);
        assert_eq!(composer_surface_inner_width(Some(50)), 48);
        assert_eq!(composer_surface_inner_width(Some(200)), 68);

        for columns in [32, 50, 70, 120] {
            let inner_width = composer_surface_inner_width(Some(columns));
            for rich in [true, false] {
                let rendered = format!(
                    "{}{}",
                    slash_palette("", rich, inner_width),
                    composer_status("模型-狐", "~/仕事/計画", rich, inner_width)
                );
                let expected_width = columns.min(COMPOSER_SURFACE_MAX_WIDTH);
                assert!(
                    rendered
                        .lines()
                        .filter(|line| !line.is_empty())
                        .all(|line| line.width() == expected_width),
                    "surface exceeded {columns} columns (rich={rich}):\n{rendered}"
                );
            }
        }

        let compact = slash_palette("mod", true, 30);
        assert!(compact.contains(" /model <name>"));
        assert!(!compact.contains("switch model while keeping history"));
    }

    #[test]
    fn slash_registry_is_sorted_unique_and_drives_help() {
        let names: Vec<_> = SLASH_COMMANDS.iter().map(|spec| spec.name).collect();
        let mut sorted = names.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(names, sorted, "registry must remain sorted and unique");

        let help = slash_help("test-model", false);
        for spec in SLASH_COMMANDS {
            match spec.alias_of {
                // Aliases fold into their parent row instead of having one.
                Some(parent) => {
                    assert!(help.contains(&format!("(alias: /{})", spec.name)));
                    assert!(
                        !help.lines().any(|line| {
                            let row = line.trim_start();
                            row == spec.syntax()
                                || row
                                    .strip_prefix(&spec.syntax())
                                    .is_some_and(|rest| rest.starts_with("  "))
                        }),
                        "alias {} has own row",
                        spec.name
                    );
                    assert!(SLASH_COMMANDS
                        .iter()
                        .any(|candidate| candidate.name == parent && candidate.alias_of.is_none()));
                }
                None => {
                    assert!(help.contains(&spec.syntax()));
                    assert!(help.contains(spec.description));
                }
            }
        }
        assert!(help.ends_with(
            "current model: test-model — /help <command> explains one command in detail"
        ));
    }

    #[test]
