        assert!(!help
            .lines()
            .any(|line| line.trim_start().starts_with("/cost ")));

        let cost_help = slash_command_help("cost");
        assert!(cost_help.starts_with("/usage [session]"));
        assert!(cost_help.contains("/cost is an alias of /usage"));
